window.ZIKRA_CONTENT=window.ZIKRA_CONTENT||{};window.ZIKRA_CONTENT.de=[{"id":2,"text":"Es gibt keinen Gott außer Allah allein, ohne Partner. Ihm gehört die Herrschaft und Ihm gebührt alles Lob, und Er ist zu allem fähig. O Allah, niemand kann zurückhalten, was Du gegeben hast, und niemand kann geben, was Du verwehrt hast, und kein Reichtum oder Glück kann irgendjemandem nützen, denn von Dir kommt aller Reichtum und alles Glück.","title":"Dua nach dem Gebet für Rizq und Hilfe","source":"Bukhari: 844","reflection":"Dieses Dua nach dem Salah erinnert uns daran, dass nur Allah allen Reichtum und Segen kontrolliert, was es zu einer starken Möglichkeit macht, nach jedem Fard-Gebet im täglichen Leben um Rizq und Hilfe zu bitten.","lesson":"Allahumma la mania lima ataita bringt Barakah in den Rizq und bewahrt den Wohlstand."},{"id":3,"text":"Niemand hat das Recht, angebetet zu werden, außer Allah allein, Der keinen Partner hat. Ihm gehört die Herrschaft und Ihm gebührt das Lob, und Er ist zu allem fähig.","title":"Kraft von La Ilaha Illallah (Befreiung eines Sklaven)","source":"Bukhari: 6404","reflection":"Das Sprechen der Kalima Tawhid bringt einen Muslim näher zu Allahs Barmherzigkeit und Macht, macht die Herzen stark und füllt das Leben mit Segen durch dieses mächtigste Dua im Islam.","lesson":"Kalima Tawhid wischt viele Sünden weg und bringt Barakah in jede Tat und jeden Tag."},{"id":4,"text":"Dir allein dienen wir, und zu Dir allein flehen wir um Hilfe.","title":"Dua für Rechtleitung (Rezitation der Sure Al-Fatiha)","source":"Sure Al-Fatiha 1:5","reflection":"Dieses Dua für Rechtleitung aus der Sure Al-Fatiha hilft Muslimen, Allah um Hilfe und Richtung zu bitten, und macht jedes Salah und jede Tat voller Hoffnung und Vertrauen auf Seine Barmherzigkeit und Weisheit.","lesson":"Iyyaka na budu wa iyyaka nastaeen bringt wahre Rechtleitung in das Leben jedes Muslims."},{"id":5,"text":"Leite mich durch das, worin es Meinungsverschiedenheiten gibt, zur Wahrheit mit Deiner Erlaubnis, wahrlich, Du leitest, wen Du willst, auf einen geraden Weg.","title":"Prophetisches Dua für Rechtleitung (Sahih Muslim)","source":"Muslim: 770","reflection":"Dieses prophetische Dua für Rechtleitung aus Sahih Muslim hilft Muslimen, den richtigen Weg zu finden, wenn die Wahrheit unklar ist, und macht Herzen fest mit Allahs Hilfe und der Bedeutung von Tauhid im Islam.","lesson":"Prophetisches Dua für Rechtleitung bringt Muslime dem Sirat al Mustaqim immer näher."},{"id":6,"text":"O Allah, hilf mir, Dir zu gedenken, Dir zu danken und Deinen Gottesdienst auf die beste Weise zu verrichten.","title":"Dua nach dem Salah für Hilfe im Gottesdienst","source":"Sahih (Albani). Abu Dawud: 1522","reflection":"Dieses Dua nach dem Salah hilft Muslimen, Allah zu gedenken, Ihm zu danken und Ibadah auf die beste Weise zu tun, was jedes Gebet voller Barakah und wahrer Taten für das Herz macht.","lesson":"Allahumma inni ala zikrika hält den Zikr stark und bringt Frieden nach jedem Namaz."},{"id":7,"text":"Leite mich zu den besten Sitten, denn niemand kann zu den besten von ihnen leiten außer Dir. Beschütze mich vor schlechten Sitten, denn niemand kann gegen sie schützen außer Dir.","title":"Dua für gutes Benehmen (Masnoon Dua)","source":"Muslim: 771","reflection":"Allah um die besten Sitten zu bitten, bringt Freundlichkeit und Respekt ins Leben, macht jede Handlung besser und hält die Herzen weich mit diesem Masnoon-Dua für guten Charakter und tägliche Taten.","lesson":"Allah leitet einen Muslim durch dieses Dua für gutes Benehmen zum besten Akhlaq."},{"id":8,"text":"O Allah, ich bitte Dich um Rechtschaffenheit und das Festhalten am geraden Weg.","title":"Dua für Rechtleitung","source":"Muslim: 2725","reflection":"Allah mit diesem mächtigen Dua um Rechtleitung und Stärke zu bitten, bringt Licht ins Herz, hilft einem Muslim, auf dem richtigen Weg zu bleiben, und hält den Iman bei jedem Schritt des täglichen Lebens stark.","lesson":"Allahumma inni Dua für Rechtleitung führt einen Muslim immer auf den geraden Weg."},{"id":9,"text":"O Allah, leite mich mit denen, die Du geleitet hast, und stärke mich mit denen, denen Du Stärke gegeben hast. Nimm mich in Deine Obhut mit denen, die Du in Deine Obhut genommen hast. Segne mich in dem, was Du mir gegeben hast. Beschütze mich vor dem Übel, das Du bestimmt hast. Wahrlich, Du befiehlst und wirst nicht befehligt, und niemand, den Du in Deine Obhut genommen hast, wird erniedrigt, und niemand, den Du als Feind genommen hast, wird Ruhm kosten. Du bist gesegnet, unser Herr, und erhaben.","title":"Mächtiges Nachtgebet im Witr (Dua Qunoot)","source":"Sahih (Albani). Abu Dawud: 1425","reflection":"Dieses mächtige Nachtgebet im Witr bringt Allahs Hilfe, Barakah und Sicherheit, macht Herzen stark und hält einen Muslim jede Nacht im Salah nahe bei Allahs Obhut.","lesson":"Dua Qunoot im Witr-Gebet bringt Allahs Hidayat und hält den Iman stark."},{"id":11,"text":"O Allah, vergib mir und nimm meine Reue an, denn Du bist der Annehmende der Reue, der Barmherzige.","title":"Dua für Vergebung (Rabbighfirli wa tub alayya innaka)","source":"Sahih (Albani). Abu Dawud: 1516","reflection":"Jeden Tag Allah um Vergebung mit diesem kurzen Dua zu bitten, bringt Frieden ins Herz, hilft einem Muslim, seine Taten zu reinigen, und hält die Hoffnung auf Allahs Barmherzigkeit und Güte lebendig.","lesson":"Rabbighfirli-Dua wischt Sünden weg und bringt Allahs Rahmah nah an das Herz."},{"id":12,"text":"Ich suche die Vergebung Allahs, des Mächtigen, außer Dem es keinen Anbetungswürdigen gibt außer Ihm, dem Lebendigen, dem Beständigen, und ich bereue vor Ihm.","title":"Dua für Vergebung großer Sünden","source":"Sahih (Albani). Tirmidhi: 3577","reflection":"Sich mit diesem Dua für Vergebung großer Sünden an Allah zu wenden, bringt Hoffnung, wischt große Fehler weg und hilft einem Muslim, Allahs Barmherzigkeit und Barakah in jedem Teil des Lebens zu fühlen.","lesson":"Astaghfirullah al adzim Dua entfernt schwere Sünden und bringt Allahs Maghfirat."},{"id":13,"text":"O Allah, ich bitte Dich um das Paradies und suche Deinen Schutz vor dem Feuer.","title":"Dua für Paradies und Schutz vor dem Höllenfeuer","source":"Sahih (Albani). Ibn Madscha: 910","reflection":"Allah mit diesem Dua um Jannah und Sicherheit vor Jahannam zu bitten, bringt Hoffnung, hält die Herzen auf das Jenseits fokussiert und hilft einem Muslim, sich jeden Tag an das wahre Ziel des Lebens zu erinnern.","lesson":"Allahumma inni asaluka macht den Wunsch eines Muslims nach Jannah in jedem Salah stark."},{"id":15,"text":"O Allah! Kontrolleur der Herzen, lenke unsere Herzen zu Deinem Gehorsam.","title":"Dua für Herzen zum Gehorsam (Sahih Muslim)","source":"Muslim: 2655","reflection":"Allah zu bitten, das Herz mit diesem Dua zu leiten, bringt Ruhe, hilft einem Muslim, auf dem richtigen Weg zu bleiben, und hält das Herz in jedem Teil des Lebens nahe an Allahs Befehlen.","lesson":"Ya muqollibal qulub hilft Herzen, weich und bereit für Allahs Hidayat zu bleiben."},{"id":16,"text":"O Veränderer der Herzen! Stärke mein Herz in Deiner Religion.","title":"Dua für Standhaftigkeit in der Religion (Masnun Dua)","source":"Sahih (Albani). Tirmidhi: 3522","reflection":"Allah zu bitten, das Herz mit diesem Dua stark in Seinem Deen zu halten, hilft einem Muslim, fest zu bleiben, bringt Frieden und hält den Iman jeden einzelnen Tag sicher vor Zweifeln und falschen Wegen.","lesson":"Ya muqallibal qulub Dua auf Arabisch hält das Herz fest im wahren Islam."},{"id":17,"text":"O Allah! Gewähre uns ein gutes Ergebnis in all unseren Angelegenheiten und bewahre uns vor der Schande dieser Welt und der Bestrafung des Jenseits.","title":"Dua für Schutz bei allen Aktivitäten (Masnoon Dua)","source":"Sahih (Suyuti). Dschami' as-Saghir: 1450","reflection":"Allah mit diesem Dua um ein gutes Ende in jeder Angelegenheit zu bitten, bringt Sicherheit, hält einen Muslim fern von Schande und hilft dem Herzen, auf Allahs Plan in dieser Welt und im nächsten Leben zu vertrauen.","lesson":"Allahumma-Dua für Schutz hält einen Muslim sicher vor allen Arten von Übel."},{"id":18,"text":"O Allah, vervollkommne mir meine Religion, von der der Erfolg all meiner Angelegenheiten abhängt, und vervollkommne mir meine weltlichen Angelegenheiten, von denen mein Lebensunterhalt abhängt, und vervollkommne mir mein Jenseits, zu dem ich zurückkehren werde, und mache im Leben für mich eine Vermehrung von allem Guten, und mache den Tod für mich zu einem Trost vor allem Übel.","title":"Dua für Erfolg im Deen (Allahumma aslih li deeni)","source":"Muslim: 2720","reflection":"Allah mit diesem Dua um Erfolg zu bitten, bringt Hilfe in Deen, Dunya und Akhirah, hält das Leben eines Muslims voller Barakah und macht jeden Tag mit Allahs Barmherzigkeit und Fürsorge besser.","lesson":"Allahumma aslih li deeni hilft, den Deen stark und Taten sicher vor Fehlern zu halten."},{"id":19,"text":"O Allah, ich suche Zuflucht bei Dir vor dem Entzug Deiner Segnung, der Veränderung Deines Schutzes, der plötzlichen Zufügung Deines Zorns und all Deiner Wut.","title":"Dua für Schutz und Suche nach Allahs Hilfe","source":"Muslim: 2739","reflection":"Dieses Dua des Schutzes bittet Allah, Seine Segnungen sicher zu halten, vor Schaden zu schützen und jedem Muslim zu helfen, in Zeiten von Ärger und Angst stark zu bleiben.","lesson":"Allah gibt Seine Barakah und hält Segnungen sicher, wenn dieses Dua für Schutz gemacht wird."},{"id":20,"text":"O Allah, ich suche Zuflucht bei Dir vor Kummer und Traurigkeit, vor Schwäche und vor Faulheit, vor Geiz und vor Feigheit, davor, von Schulden überwältigt und von Männern (d.h. anderen) bezwungen zu werden.","title":"Dua für Stress, Angst und Depression","source":"Bukhari: 2893","reflection":"Dieses Dua für Stress und Traurigkeit hilft einem Muslim, Frieden, Stärke und Erleichterung von schweren Gefühlen zu finden, und bittet Allah, Sorgen, Schulden und alle Arten von Härte aus dem Leben zu entfernen.","lesson":"Allah entfernt Traurigkeit und gibt Frieden, wenn dieses Dua für Stress mit Iman gemacht wird."},{"id":22,"text":"Gepriesen sei Allah und gelobt sei Er.","title":"Dua für Vergebung der Sünden","source":"Bukhari: 6405","reflection":"Dieses Dua für Vergebung der Sünden bringt Allahs Barmherzigkeit, wischt Fehler weg und füllt das Herz mit Barakah und Frieden für jeden Muslim, der es mit Iman sagt.","lesson":"Allah vergibt viele Sünden, wenn ein Muslim Subhanallahi wa bihamdihi sagt."},{"id":23,"text":"Ruhm sei Allah und alles Lob gebührt Ihm, Ruhm sei Allah, dem Großen.","title":"Dhikr für Vergebung (Subhanallah Wa Bihamdihi Dua)","source":"Bukhari: 6406","reflection":"Dieser Dhikr und Dua bringt Allahs Vergebung, füllt das Herz mit Barakah und lässt die Taten jedes Muslims mit den Segnungen von Allahs Lobpreisung, Größe und Barmherzigkeit strahlen.","lesson":"Allah vergibt viele Sünden, wenn ein Muslim Subhanallahi wa bihamdihi subhanallahil azeem sagt."},{"id":24,"text":"Wie perfekt Allah ist, und alles Lob ist für Allah. Niemand hat das Recht, angebetet zu werden, außer Allah, und Allah ist der Größte.","title":"Mächtiger Dhikr, der Allah geliebt ist (Masnun Dua)","source":"[1] Muslim: 2137 [2] Muslim: 2695","reflection":"Dieser mächtige Zikr bringt Herzen näher zu Allah und füllt das Leben mit Barakah, da diese Worte von Allah geliebt werden und für jeden Muslim in jedem Moment leicht zu sagen sind.","lesson":"Subhanallah walhamdulillah wala ilaha illallah wallahu akbar bringt riesige Belohnung von Allah und macht den Iman stark."},{"id":25,"text":"Wie perfekt Allah ist.","title":"Nutzen des Sagens von Subhan Allah","source":"Muslim: 2698","reflection":"SubhanAllah zu sagen bringt einen Muslim näher zu Allahs Liebe und Vergebung, macht Herzen sauber und füllt jeden Abend mit Frieden und Segen vom besten Dhikr.","lesson":"SubhanAllah auf Arabisch entfernt kleine Sünden und bringt Barakah in Taten."},{"id":26,"text":"Im Namen Allahs, des Gnadenvollen, des Barmherzigen. (1) Sprich: „Er ist Allah, ein Einer, (2) Allah, der Überlegene. (3) Er hat nicht gezeugt und ist nicht gezeugt worden, (4) und Ihm ebenbürtig ist keiner.“ (Sure Ikhlas: 1-4)","title":"Nutzen der täglichen Rezitation der Sure Ikhlas","source":"Sahih (Albani). Sahih al-Dschami: 6472","reflection":"Sure Ikhlas bringt riesige Belohnung und macht den Iman stark, da diese kurze Sure einem Drittel des Quran entspricht und das Herz jeden Tag mit Liebe zu Allah füllt.","lesson":"Sure Ikhlas auf Arabisch gibt Belohnung wie das Lesen eines Drittels des Quran."},{"id":27,"text":"Wie perfekt Allah ist, Der Höchste, und ich preise Ihn.","title":"Tägliches Dua für das Pflanzen eines Baumes im Jannah","source":"Sahih (Albani). Tirmidhi: 3464","reflection":"Dieses Dua für Jannah hilft einem Muslim, Bäume im Paradies zu verdienen, und bringt Allahs Lob und Barmherzigkeit näher, was jeden Tag voller Hoffnung und Belohnung für das Jenseits macht.","lesson":"Subhanallahi wa bihamdihi subhanallahil azeem pflanzt einen Baum im Jannah."},{"id":28,"text":"Es gibt keine Macht noch Kraft außer bei Allah.","title":"Dua für Jannah (Lahaula Walaquwata)","source":"Bukhari: 6384","reflection":"Dieses Jannat-Dua erinnert jeden Muslim daran, dass alle Stärke allein von Allah kommt, bringt Hoffnung, Belohnung und Hilfe in jeder schweren Zeit für diejenigen, die auf Seine Macht vertrauen.","lesson":"La hawla wala quwwata illa billah auf Arabisch öffnet Türen zum Jannah für Muslime."},{"id":29,"text":"Niemand hat das Recht, angebetet zu werden, außer Allah, allein ohne Partner. Allah ist sehr groß und viel Lob ist für Allah. Wie perfekt Allah ist, Herr der Welten. Es gibt keine Macht noch Kraft außer bei Allah, dem Erhabenen an Macht, dem Weisen.","title":"Dua allen Lobes für Allah (Masnoon Dua)","source":"Muslim: 2696","reflection":"Dieses Dua, das Allah preist, bringt einen Muslim näher zu Ihm, füllt das Herz mit Dankbarkeit und erinnert uns an Allahs Größe, Barmherzigkeit und Macht in jedem Teil des täglichen Lebens.","lesson":"Allahs Hilfe kommt zu dem, der La ilaha illalahu mit vollem Iman sagt."},{"id":30,"text":"O Allah, vergib mir, habe Barmherzigkeit mit mir, leite mich und gewähre mir Versorgung.","title":"Dua nach der Annahme des Islams (Masnun Dua)","source":"Muslim: 2697","reflection":"Dieses Dua nach der Annahme des Islams hilft einem neuen Muslim, Allah um Vergebung, Barmherzigkeit, Rechtleitung, Sicherheit und Rizq zu bitten, was den Beginn seiner Iman-Reise voller Hoffnung und Barakah macht.","lesson":"Allahummaghfirli Warhamni bringt Allahs Vergebung und deckt alte Sünden zu."},{"id":31,"text":"Alles Lob gebührt Allah.","title":"Mächtigster Dhikr und Dua im Islam","source":"Hasan (Albani). Tirmidhi: 3383","reflection":"Alhamdulillah zu sagen füllt das Herz mit Shukr (Dankbarkeit), bringt Frieden und hält einen Muslim nahe bei Allah, was jeden Moment voll Barakah und Hoffnung im täglichen Leben macht.","lesson":"Die Bedeutung von Alhamdulillah lehrt einen Muslim, Allah in jedem Amal zu danken."},{"id":32,"text":"Wie perfekt Allah ist, und alles Lob ist für Allah. Niemand hat das Recht, angebetet zu werden, außer Allah, und Allah ist der Größte. Es gibt keine Macht noch Kraft außer bei Allah.","title":"Mächtiger Dhikr, der ewig im Jannah währt","source":"Musnad Ahmad (Nr. 513) (Ahmad Shakir, Hrsg.) und seine Überlieferungskette ist authentisch. Siehe Madschma' az-Zawa'id 1/297. Ibn Hadschar erwähnt es in Bulugh al-Maram und sagt, dass Ibn Hibban und Al-Hakim es als authentisch einstuften.","reflection":"Dieser Dhikr und Dua füllt das Herz mit Iman, bringt Allahs Barmherzigkeit und gibt Belohnungen, die für immer im Jannah bleiben, was die Taten jedes Muslims stark und voll Barakah macht.","lesson":"Die Bedeutung von Subhanallah hilft einem Muslim, die Zunge mit Allahs Zikr sauber zu halten."},{"id":36,"text":"(1) Wahrlich, Wir sandten ihn (den Koran) herab in der Nacht der Bestimmung. (2) Und was lässt dich wissen, was die Nacht der Bestimmung ist? (3) Die Nacht der Bestimmung ist besser als tausend Monate. (4) In ihr kommen die Engel und der Geist mit der Erlaubnis ihres Herrn für jede Angelegenheit herab. (5) Frieden ist sie bis zum Anbruch der Morgenröte.","title":"Nutzen der Sure Laylatul Qadr","source":"Sure Al-Qadr 97:1-5","reflection":"Sure Al Qadr erzählt von der Nacht der Macht, bringt riesige Belohnungen, Frieden und Segnungen für Muslime, die lesen und an ihre Botschaft glauben, was jede Ramadan-Nacht voller Hoffnung macht.","lesson":"Sure Al Qadr bringt Belohnung besser als tausend Monate an Taten."},{"id":37,"text":"O Allah, Du bist Allvergebend, Großzügig. Du liebst Vergebung; so vergib mir.","title":"Laylatul Qadr Dua für Vergebung","source":"Sahih (Albani). Tirmidhi: 3513","reflection":"In der gesegneten Nacht von Laylatul Qadr bringt dieses Dua für Vergebung Hoffnung und Barmherzigkeit, und hilft jedem Muslim, Allahs Verzeihung und Barakah in den letzten 10 Tagen des Ramadan zu suchen.","lesson":"Allahs Barmherzigkeit bedeckt das Herz eines Muslims, der Laylatul Qadr Dua macht."},{"id":39,"text":"(17) Sie pflegten nur wenig in der Nacht zu schlafen, (18) Und in den Stunden vor der Morgendämmerung pflegten sie um Vergebung zu bitten. [2]","title":"Dua für Vergebung zur Tahajjud-Zeit","source":"[1] Bukhari: 1145 [2] Sure Az-Zariyat: 51: 17-18","reflection":"","lesson":""},{"id":45,"text":"Niemand hat das Recht, angebetet zu werden, außer Allah. Er ist der Einzige und hat keine Partner. Ihm gehört das Königreich und alles Lob gebührt Ihm. Er ist allmächtig. Alles Lob ist für Allah. Aller Ruhm ist für Allah. Und niemand hat das Recht, angebetet zu werden, außer Allah, und Allah ist groß und es gibt weder Macht noch Kraft außer bei Allah.","title":"Dua beim Aufwachen in der Nacht (Masnun Dua)","source":"Bukhari: 1154","reflection":"Dieses Dua in der Nacht füllt das Herz mit Allahs Lob und Macht, hilft Muslimen, sich nach dem Schlaf an Ihn zu erinnern, und bringt Frieden und Barakah in den ruhigen Stunden vor Fajr.","lesson":"Allahs Hilfe kommt dem nahe, der Dua macht, wenn er nachts aufwacht."},{"id":46,"text":"Es gibt keinen Anbetungswürdigen außer Dir, gepriesen bist Du. Wahrlich, ich war unter den Ungerechten.","title":"Dua des Yunus (La Ilaha Illa Anta Subhanaka)","source":"Sahih (Albani). Tirmidhi: 3505","reflection":"Dieses Dua des Yunus bringt Hoffnung und Erleichterung für Muslime, die Schwierigkeiten haben, und hilft Herzen, Allahs Barmherzigkeit und Vergebung in Zeiten von Not und Härte zu finden.","lesson":"Allah entfernt Schwierigkeiten für denjenigen, der mit dem Dua des Yunus in harten Zeiten ruft."},{"id":47,"text":"Wir sind von Allah und zu Ihm kehren wir zurück. O Allah, nimm mich aus meiner Notlage heraus und bringe mir danach etwas Besseres.","title":"Dua für Unglück (Masnoon Dua)","source":"Muslim: 918","reflection":"Dieses Dua für Not hilft Muslimen, Hoffnung und Geduld in harten Zeiten zu finden, und bittet Allah um Belohnung und etwas Besseres nach jeder Prüfung oder jedem Verlust.","lesson":"Allah gibt Sabr und Belohnung demjenigen, der Dua für Not im Unglück macht."},{"id":49,"text":"Allah ist der Größte, sehr Groß. Lob ist für Allah, reichlich. Ehre sei Allah, beim Anbruch des Tages und an seinem Ende.","title":"Dua vor Beginn des Salah","source":"Muslim: 601","reflection":"Dieses Dua vor dem Salat füllt das Herz mit Lob für Allah und hilft Muslimen, ihr Salah mit Barakah und einem starken Fokus auf Iman und Taten zu beginnen.","lesson":"Allahu Akbar Kabira Walhamdulillah Kathira bringt Frieden vor jedem Salah."},{"id":50,"text":"Lob ist für Allah, viel, gutes und gesegnetes Lob.","title":"Dua zu Beginn des Salah","source":"Muslim: 600","reflection":"Dieses Dua vor Namaz füllt das Herz mit Lob für Allah und bringt Barakah, was jedes Salah mit Dankbarkeit und einem sauberen Geist bereit für die Anbetung beginnen lässt.","lesson":"Allah gibt mehr Barakah im Salah, wenn Muslime mit Dua zu Beginn des Salah beginnen."},{"id":52,"text":"Unser Herr, Dir gebührt Lob, reichliches, gutes und gesegnetes Lob.","title":"Dua nach Ruku (Rabbana Lakal Hamdu)","source":"Bukhari: 799","reflection":"Dieses Dua nach Ruku füllt dein Salah mit Lob und Dank, bringt mehr Barakah und Nähe zu Allah und macht deinen Namaz stärker mit jedem Wort, das du von Herzen sagst.","lesson":"Allah gibt mehr Barakah im Salah, wenn Muslime Rabbana Lakal Hamd nach Ruku sagen."},{"id":54,"text":"O Allah, unser Herr und Dir gebührt das Lob.","title":"Dua nach Ruku (Rabbana Lakal Hamdu)","source":"Bukhari: 796","reflection":"Dieses Dua nach Ruku bringt mehr Lob für Allah im Salah, macht jede Rakah voll Dank und Barakah und hilft Muslimen, ihren Namaz stark und nah an der Sunnah zu halten.","lesson":"Allah liebt es, wenn Muslime Rabbana Lakal Hamd nach Ruku in jedem Salah sagen."},{"id":55,"text":"O Allah, ich bitte Dich, O Allah, da Du der Eine, der Einzige, der unabhängige Herr bist, der weder zeugt noch gezeugt wurde, und dem niemand gleich oder vergleichbar ist, vergib mir meine Sünden, denn Du bist der Allvergebende, Barmherzigste.","title":"Dua vor dem Salam","source":"Sahih (Albani). Nasa'i: 1301","reflection":"Dieses Salam Dua vor Beendigung des Salah bringt Hoffnung auf Vergebung und Barmherzigkeit, und lässt jeden Muslim Allah bei Seinen schönen Namen bitten und Frieden im Herzen finden, bevor er Salam sagt.","lesson":"Allah vergibt Sünden, wenn Muslime dieses Salam Dua mit wahrem Herzen im Namaz machen."},{"id":56,"text":"O Allah, ich bitte Dich aufgrund der Tatsache, dass Dir das Lob gebührt, es gibt keinen Gott außer Dir, Der Gunst und Wohltaten erweist, der Schöpfer der Himmel und der Erde, O Herr der Majestät und Pracht, O Lebendiger, O Ewiger.","title":"Dua vor dem Salam","source":"Sahih (Albani). Abu Dawud: 1495","reflection":"Dieses Dua nach Attahiyat füllt das Herz mit Lob für Allah, macht das Salah stärker und bringt Hoffnung auf Seine Hilfe, Barmherzigkeit und Barakah, bevor in jedem Gebet Salam gesagt wird.","lesson":"Allah gibt mehr Barakah im Salah, wenn Muslime dieses Dua nach Attahiyat sagen."},{"id":57,"text":"O Allah, ich bitte Dich, bei der Tatsache, dass ich bezeuge, dass Du Allah bist. Es gibt keinen anbetungswürdigen außer Dir, dem Einzigen Gott, Unabhängig von der Schöpfung, der nicht gezeugt wurde und nicht zeugt, und niemand ist Ihm gleich.","title":"Dua nach Tashahhud (Dua vor Salam)","source":"Sahih (Albani). Abu Dawud: 1493","reflection":"Dieses Dua nach Tashahhud macht das Salah stärker, indem es Allahs Einzigkeit preist, und hilft Muslimen, vor dem Salam in jedem Gebet mit reinem Herzen um alles zu bitten.","lesson":"Allahumma Inni As'aluka in diesem Dua nach Tashahhud bringt mehr Barakah im Salah."},{"id":58,"text":"Ich bezeuge, dass niemand das Recht hat, angebetet zu werden, außer Allah allein, Der keinen Partner hat; und ich bezeuge, dass Muhammad (ﷺ) Sein Diener und Sein Gesandter ist.","title":"Dua nach Wudu (Gebetswaschung)","source":"Muslim: 234","reflection":"Dieses Dua nach der Waschung bringt einen Muslim näher zu Allah, macht jedes Wudu spezieller und voller Barakah, während es das Herz sauber und den Iman stark für Salah und täglichen Amal hält.","lesson":"Allah öffnet alle acht Türen von Jannah für denjenigen, der dieses Dua nach Wudu sagt."},{"id":68,"text":"Niemand hat das Recht, angebetet zu werden, außer Allah. Er ist der Einzige und hat keine Partner. Ihm gehört das Königreich und alles Lob gebührt Ihm. Er ist allmächtig. Alles Lob ist für Allah. Aller Ruhm ist für Allah. Und niemand hat das Recht, angebetet zu werden, außer Allah, und Allah ist groß und es gibt weder Macht noch Kraft außer bei Allah.","title":"Dua nach dem Aufwachen in der Nacht (La Ilaha Illalahu Wa'hdahu)","source":"Bukhari: 1154","reflection":"Dieses Dua nach dem Aufwachen in der Nacht füllt das Herz mit Allahs Lob und bringt Barakah, was die Nacht friedlich und den Iman stark für jeden Muslim macht, der in den ruhigen Stunden Allahs gedenkt.","lesson":"Allah gibt dem Muslim, der La Ilaha Illalahu nach dem Aufwachen sagt, besonderen Lohn."},{"id":72,"text":"Es gibt keinen anbetungswürdigen außer Dir, Ehre sei Dir. Wahrlich, ich war unter den Ungerechten.","title":"Dua von Yunus (La Ilaha Illa Anta Subhanaka)","source":"Sahih (Albani). Tirmidhi: 3505","reflection":"Dieses Dua von Yunus bringt Hoffnung und Vergebung für jeden Muslim, hilft Herzen, Frieden und Barakah zu finden, während es einfach macht, Allah in Zeiten von Schwierigkeiten und Traurigkeit um Hilfe zu bitten.","lesson":"Allah entfernt große Probleme für denjenigen, der das Dua von Yunus mit wahrem Herzen macht."},{"id":74,"text":"O Allah, ich bitte Dich aufgrund der Tatsache, dass ich bezeuge, dass Du Allah bist. Es gibt keinen anbetungswürdigen außer Dir, dem Einzigen Gott, Unabhängig von der Schöpfung, Der nicht gezeugt wurde und nicht zeugt, und niemand ist Ihm gleich.","title":"Dua für die Größten Namen Allahs (Ism-E-Azam)","source":"Sahih (Albani). Nasa'i: 1300","reflection":"Dieses Dua mit den Namen Allahs bringt einen Gläubigen näher zu Allahs Barmherzigkeit und Hilfe, öffnet Tore von Barakah und macht das Herz stark mit Iman und Hoffnung in jedem Teil des Lebens.","lesson":"Allah antwortet auf das Namen Allahs Dua schnell, wenn ein Muslim mit vollem Iman ruft."},{"id":75,"text":"O Allah, ich bitte Dich aufgrund der Tatsache, dass Dir das Lob gebührt, es gibt keinen Gott außer Dir, Der Gunst und Wohltaten erweist, der Schöpfer der Himmel und der Erde, O Herr der Majestät und Pracht, O Lebendiger, O Ewiger.","title":"Dua nach Tashahhud (Allahumma inni as aluka)","source":"Sahih (Albani). Nasa'i: 1300","reflection":"Dieses Dua nach Attahiyat bringt einen Muslim näher zu Allahs Barmherzigkeit und Hilfe, macht jeden Namaz voll von Barakah und Hoffnung, indem man Allah mit Seinen schönen Namen und Lob anruft.","lesson":"Allahumma Inni As'aluka im Tashahhud macht Dua nach Namaz akzeptierter."},{"id":78,"text":"Wir haben den Morgen erreicht und zu dieser Zeit gehört Allah alle Herrschaft, und alles Lob ist für Allah. Niemand hat das Recht, angebetet zu werden, außer Allah, allein, ohne irgendeinen Partner, Ihm gehören alle Herrschaft und Lob und Er ist über alle Dinge allmächtig. Mein Herr, ich bitte Dich um das Gute dieses Tages und das Gute dessen, was ihm folgt, und ich nehme Zuflucht bei Dir vor dem Übel dieses Tages und dem Übel dessen, was ihm folgt. Mein Herr, ich nehme Zuflucht bei Dir vor Faulheit und Altersschwäche. Mein Herr, ich nehme Zuflucht bei Dir vor Pein im Feuer und Strafe im Grab.","title":"Morgen-Dua für Schutz und Segnungen","source":"","reflection":"Starte deinen Tag mit diesem Morgen-Dua, um Allahs Barakah nahe zu halten, um gute Dinge und Sicherheit vor Schaden zu bitten, was jeden Morgen voll Hoffnung und Segnungen für einen Muslim macht.","lesson":"Asbahna Wa Asbahal Mulku Lillah hält das Herz sicher vor Shaitan und Übel."},{"id":79,"text":"Wir haben den Abend erreicht und zu dieser Zeit gehört Allah alle Herrschaft, und alles Lob ist für Allah. Niemand hat das Recht, angebetet zu werden, außer Allah, allein, ohne irgendeinen Partner, Ihm gehören alle Herrschaft und Lob und Er ist über alle Dinge allmächtig. Mein Herr, ich bitte Dich um das Gute dieser Nacht und das Gute dessen, was ihr folgt, und ich nehme Zuflucht bei Dir vor dem Übel dieser Nacht und dem Übel dessen, was ihr folgt. Mein Herr, ich nehme Zuflucht bei Dir vor Faulheit und Altersschwäche. Mein Herr, ich nehme Zuflucht bei Dir vor Pein im Feuer und Strafe im Grab.","title":"Masnoon Abend-Dua rezitiert vom Propheten ﷺ","source":"Muslim: 2723","reflection":"Dieses Abend-Dua ist ein Schild für Muslime, das Allah um Barakah, Schutz vor Übel und Segnungen in der Nacht bittet, so wie es der Prophet ﷺ tat, was Frieden und Sicherheit ins Herz vor dem Schlaf bringt.","lesson":"Rezitiere bei Sonnenuntergang Abend-Dua für Schutz und Segnungen, wenn die Nacht beginnt."},{"id":80,"text":"O Allah, durch Dich treten wir in den Morgen ein und durch Dich treten wir in den Abend ein, durch Dich leben wir und durch Dich sterben wir, und zu Dir ist unsere Auferstehung.","title":"Morgen-Dua für Schutz (Morgen-Azkar)","source":"","reflection":"Starte deinen Tag mit diesem Morgen-Dua für Schutz, bitte Allah, dich sicher zu halten, Barakah zu bringen und dein Herz mit Seiner Barmherzigkeit von Fajr bis zur Nacht zu leiten.","lesson":"Allahumma in diesem Morgen-Dua bringt Hifazat und Frieden in das Herz eines Muslims."},{"id":81,"text":"O Allah, durch Dich treten wir in den Abend ein und durch Dich treten wir in den Morgen ein, durch Dich leben wir und durch Dich sterben wir, und zu Dir ist unsere Auferstehung.","title":"Gebete für den Abend (Masnun Dua)","source":"Sahih (Albani). Abu Dawud: 5068","reflection":"Finde Frieden und Sicherheit, wenn die Sonne untergeht, indem du dieses Abend-Dua machst, Allah bittest, deinen Iman stark und deine Familie sicher zu halten mit Seiner Barmherzigkeit und Barakah jede Nacht.","lesson":"Allahumma in diesem Abend-Dua bringt Hifazat und Ruhe in das Herz bei Nacht."},{"id":82,"text":"Wir haben den Morgen erreicht und zu dieser Zeit gehört alle Herrschaft Allah, dem Herrn der Welten. O Allah, ich bitte Dich um das Gute dieses Tages, seine Triumphe und seine Siege, sein Licht und seine Segnungen und seine Führung, und ich nehme Zuflucht bei Dir vor dem Übel dieses Tages und dem Übel, das ihm folgt.","title":"Dua am Morgen für Segnungen und Schutz","source":"","reflection":"Starte deinen Tag mit diesem Dua für den Morgen, bitte Allah um Barakah, Hilfe und Sicherheit, damit dein Herz stark bleibt und dein Amal Licht und Führung von Fajr bis zur Nacht erhält.","lesson":"Asbahna Wa Asbahal Mulku Lillah bringt Barkat und Noor in jeden neuen Morgen."},{"id":83,"text":"Wir haben den Abend erreicht und zu dieser Zeit gehört alle Herrschaft Allah, dem Herrn der Welten. O Allah, ich bitte Dich um das Gute dieses Tages, seine Triumphe und seine Siege, sein Licht und seine Segnungen und seine Führung, und ich nehme Zuflucht bei Dir vor dem Übel dieses Tages und dem Übel, das ihm folgt.","title":"Abend-Dua für Führung und Segnungen","source":"Abu Dawud 4/322, Nr. 5084","reflection":"Beende deinen Tag mit diesem Abend-Dua für Führung und Segnungen, bitte Allah, deine Nacht mit Barakah, Sicherheit und Noor zu füllen, dein Herz Ihm nahe zu halten bis zum Morgen.","lesson":"Amsaynaa Wa Amsal Mulku Lillah bringt Barkat und Frieden in jede Nacht."},{"id":84,"text":"Wir stehen am Morgen auf der Fitrah des Islam auf, und dem Wort des reinen Glaubens, und der Religion unseres Propheten Muhammad und der Religion unseres Vorvaters Ibrahim, der ein Muslim und von wahrem Glauben war und nicht zu denen gehörte, die Allah andere beigesellen.","title":"Morgen-Dua für Islamische Fitrah (Masnun Dua)","source":"","reflection":"Starte deinen Tag mit diesem Morgengebet, bitte Allah, deinen Iman stark zu halten, dein Herz auf dem Pfad des Islam und deinen Amal rein wie Nabi Ibrahim und Prophet Muhammad.","lesson":"Asbahnaa 'Alaa Fitratil-Islaami hält einen Muslim jeden Morgen fest im Deen E Islam."},{"id":85,"text":"Wir stehen am Abend auf der Fitrah des Islam auf, und dem Wort des reinen Glaubens, und der Religion unseres Propheten Muhammad und der Religion unseres Vorvaters Ibrahim, der ein Muslim und von wahrem Glauben war und nicht zu denen gehörte, die Allah andere beigesellen.","title":"Abend-Dua für Glaube (Masnun Dua)","source":"Sahih (Albani). Sahih al-Dschami: 4674","reflection":"Dieses Abendgebet hilft einem Muslim, den Iman stark und rein zu halten, erinnert uns an den Pfad von Muhammad und Nabi Ibrahim, und bringt jeden Abend Frieden und Barakah ins Herz.","lesson":"Allah gibt demjenigen Barakah, der dieses Abendgebet mit wahrem Iman macht."},{"id":86,"text":"Ich suche Allahs Vergebung und ich wende mich Ihm in Reue zu.","title":"Morgen- & Abend-Istighfar Dua für Sünden","source":"Bukhari: 6307, Muslim: 2702","reflection":"Dieser Morgen-Abend-Adhkar bringt einen Muslim näher an Allahs Barmherzigkeit, hilft Herzen, sauber und hoffnungsvoll zu bleiben, indem um Vergebung gebeten und sich Ihm mit wahrer Tawbah jeden Tag zugewandt wird.","lesson":"Allah vergibt Sünden für denjenigen, der dieses Istighfar Dua im Morgen-Abend-Adhkar sagt."},{"id":87,"text":"Wie perfekt Allah ist! Ich preise Ihn bei der Anzahl Seiner Schöpfung und Seinem Wohlgefallen, und beim Gewicht Seines Thrones, und der Tinte Seiner Worte.","title":"Subhanallahi Wa Bihamdihi Dua (Morgen-Dua)","source":"Muslim: 2726","reflection":"Dieses Dua des Morgens füllt das Herz mit Lob für Allah, bringt Frieden und Barakah, und hilft einem Muslim, sich an Seine Größe und Barmherzigkeit vom Start des Tages an zu erinnern.","lesson":"Subhanallahi Wa Bihamdihi bringt endlose Barakah am Morgen für einen Muslim."},{"id":88,"text":"O Allah, schenke Muhammad (ﷺ) Deine Gunst und der Familie von Muhammad (ﷺ), wie Du Ibrahim (A) Deine Gunst geschenkt hast und der Familie von Ibrahim, Du bist Preiswürdig, Ruhmreich. O Allah, segne Muhammad und die Familie von Muhammad, wie Du Ibrahim gesegnet hast und die Familie von Ibrahim, Du bist Preiswürdig, Ruhmreich.","title":"Dua für Morgen & Abend (Durood Ibrahim)","source":"At-Tabarani, Sahih at-Targhib wa at-Tarhib 1/273","reflection":"Durood Ibrahim bringt Segnungen für Herz und Heim, macht jeden Morgen und Abend voller Barakah, Liebe für Muhammad und Nähe zu Allahs Barmherzigkeit.","lesson":"Durood Ibrahim bringt Allahs Barakah für den, der es morgens und abends sendet."},{"id":89,"text":"Im Namen Allahs, mit dessen Namen nichts auf Erden noch im Himmel geschadet wird, und Er ist Der Allhörende, Der Allwissende.","title":"Morgen- & Abend-Dua für Schutz","source":"Sahih (Albani). Abu Dawud: 5088","reflection":"Dieses Dua für Schutz vor Schaden hält einen Muslim sicher durch Allahs Namen, macht jeden Morgen und Abend voller Frieden, Sicherheit und Vertrauen in Seine Macht und Wissen.","lesson":"Bismillah hält Schaden fern von demjenigen, der dieses Dua für Schutz sagt."},{"id":90,"text":"Allah genügt mir, niemand hat das Recht, angebetet zu werden, außer Ihm, auf Ihn verlasse ich mich und Er ist der Herr des erhabenen Thrones.","title":"Hasbiyallahu Dua (Morgen- & Abend-Azkar)","source":"Sahih Mauquf (Schu'aib und Arnaut). Abu Dawud: 5081","reflection":"Beginne und beende deinen Tag mit diesem mächtigen Morgen- und Abend-Adhkar, vertraue auf Allahs Fürsorge und Barmherzigkeit, und finde Frieden in deinem Herz, indem du Hasbiyallah mit vollem Iman und Hoffnung sagst.","lesson":"Allah ist genug für mich bringt Ruhe und entfernt Angst aus dem Herzen."},{"id":91,"text":"O Ewig Lebender, O Selbst-Bestehender und Unterstützer von allem, durch Deine Barmherzigkeit suche ich Hilfe, verbessere für mich alle meine Angelegenheiten und überlasse mich nicht mir selbst, sogar für das Blinzeln eines Auges.","title":"Ya Hayyu Ya Qayyum Vollständiges Dua (Morgen Abend Azkar)","source":"Hasan (Albani). Silsila Sahiha: 227","reflection":"Dieser Azkar für Morgen und Abend bringt Allahs Barmherzigkeit nahe, hilft jedes Problem zu lösen und hält einen Muslim sicher vor Traurigkeit und Stress, indem Ya Hayyu Ya Qayyum mit vollem Vertrauen angerufen wird.","lesson":"Ya Hayyu Ya Qayyum Dua für Morgen und Abend bringt Allahs Hilfe in jeder Angelegenheit."},{"id":92,"text":"Ich bin zufrieden mit Allah als Herrn, und dem Islam als Religion und Muhammad (ﷺ) als Propheten.","title":"Morgen- & Abend-Dua für starken Iman","source":"Sahih li ghairihi (Schu'aib al-Arnaut). Tachridsch al-Musnad: 23112","reflection":"Dieses Dua für Morgen und Abend füllt das Herz mit Iman, bringt Frieden und hilft einem Muslim, glücklich mit Allah, Islam und dem Propheten zu bleiben, was jeden Tag besser mit starkem Glauben macht.","lesson":"Dieses Dua für Morgen und Abend zu sagen hält Iman stark im Herzen."},{"id":93,"text":"O Allah, ich gab meine Ehre als Almosen / Sadaka an Deine Diener.","title":"Morgen- & Abend-Dua für Vergebung","source":"Sahih Maktu (Albani). Abu Dawud: 4886","reflection":"Dieses Dua für Vergebung am Morgen und Abend hilft einem Muslim, Ärger loszulassen, bringt Allahs Barmherzigkeit und füllt das Herz mit Frieden, indem Ehre als Sadqah für andere gegeben wird.","lesson":"Allahumma Inni Dua für Vergebung wischt Sünden weg und bringt Maghfirat."},{"id":95,"text":"O Allah, Du bist mein Herr, niemand hat das Recht, angebetet zu werden, außer Dir, Du hast mich erschaffen und ich bin Dein Diener und ich halte mich an Deinen Bund und Dein Versprechen, so gut ich kann. Ich nehme Zuflucht bei Dir vor dem Übel dessen, was ich begangen habe. ich erkenne Deine Gunst mir gegenüber an und ich erkenne meine Sünde an, also vergib mir, denn wahrlich niemand kann Sünden vergeben außer Dir.","title":"Bestes Dua für Vergebung (Sayyidul Istigfar)","source":"Bukhari: 6306","reflection":"Dieses mächtige Dua, bekannt als Sayyidul Istigfar, bringt Hoffnung und Barmherzigkeit für jeden Muslim, der Allahs Vergebung mit einem wahren Herzen sucht und Iman jeden Tag stark halten will.","lesson":"Allahs Barmherzigkeit bedeckt denjenigen, der Sayyidul Istigfar mit einem wahren Herzen macht."},{"id":96,"text":"Allah! Es gibt keinen anbetungswürdigen außer Ihm, dem Ewig Lebenden, dem Einen, Der alles existierende erhält und beschützt. Weder Schlummer noch Schlaf überkommen Ihn. Ihm gehört, was in den Himmeln und was auf der Erde ist. Wer ist es, der bei Ihm Fürsprache einlegen kann, außer mit Seiner Erlaubnis? Er weiß, was ihnen in dieser Welt passiert und was ihnen im Jenseits passieren wird. Und sie werden niemals etwas von Seinem Wissen umfassen, außer dem, was Er will. Sein Thron erstreckt sich über die Himmel und die Erde, und Er empfindet keine Ermüdung beim Bewachen und Bewahren von ihnen. Und Er ist der Höchste, der Größte.","title":"Ayatul Kursi - Der Thronvers (Masnun Dua)","source":"Bukhari: 2311","reflection":"Ayatul Kursi bringt starke Sicherheit und Frieden von Allah, lässt jeden Muslim sich sicher und Ihm nahe fühlen, wenn dieser Vers mit Iman und Hoffnung im Herzen gelesen wird.","lesson":"Allahs Hifazat bedeckt denjenigen, der Ayatul Kursi nach jedem Salah nahe hält."},{"id":99,"text":"Unser Herr, vergib uns und unseren Brüdern, die uns im Glauben vorausgegangen sind, und setze nicht in unsere Herzen [irgendwelchen] Groll gegenüber denen, die geglaubt haben. Unser Herr, wahrlich Du bist Gütig und Barmherzig.","title":"Dua für Schutz vor Hass","source":"Sure Al-Haschr 59:10","reflection":"Dieses Dua für Vergebung aus Surah Hashr hilft, das Herz sauber zu halten und bringt Allahs Güte, lässt jeden Muslim Frieden und Liebe für andere im täglichen Leben fühlen.","lesson":"Allahs Barmherzigkeit bedeckt denjenigen, der dieses Dua für Vergebung mit Iman macht."},{"id":100,"text":"O Allah, gewähre meinem Körper Gesundheit, O Allah, gewähre meinem Gehör Gesundheit, O Allah, gewähre meiner Sicht Gesundheit. Niemand hat das Recht, angebetet zu werden, außer Dir. O Allah, ich nehme Zuflucht bei Dir vor Unglauben und Armut, und ich nehme Zuflucht bei Dir vor der Strafe des Grabes. Niemand hat das Recht, angebetet zu werden, außer Dir.","title":"Dua am Morgen & Abend (Dua für Gesundheit)","source":"Hasan (Albani). Abu Dawud: 5090","reflection":"Starte deinen Tag und beende ihn mit diesem Dua für Gesundheit, bitte Allah um starken Körper, gutes Gehör, klare Sicht und Sicherheit vor Schaden, Armut, Unglauben und der Strafe des Grabes.","lesson":"Allahumma Afini Fi Badani hält den Körper eines Muslims sicher vor Krankheit und Schmerz."},{"id":101,"text":"O Allah, Kenner des Verborgenen und des Sichtbaren, Schöpfer der Himmel und der Erde, Herr und Souverän aller Dinge, ich bezeuge, dass niemand das Recht hat, angebetet zu werden, außer Dir. Ich nehme Zuflucht bei Dir vor dem Übel meiner Seele und vor dem Übel und Shirk des Teufels, und davor, Unrecht gegen meine Seele zu begehen oder solches über einen anderen Muslim zu bringen.","title":"Morgendua für Schutz vor dem Bösen","source":"Sahih (Albani). Tirmidhi: 3529","reflection":"Beginne deinen Morgen mit diesem Dua für Schutz, bitte Allah, dich sicher vor deinen eigenen Fehlern, dem Schaden von Shaitan und jedem Übel zu halten, das dich oder andere Muslime berühren kann.","lesson":"Allahumma schirmt einen Muslim vor Shaitans Übel und seinem Shirk im täglichen Leben ab."},{"id":102,"text":"O Allah, ich bitte Dich um Vergebung und Wohlbefinden in diesem Leben und dem nächsten. O Allah, ich bitte Dich um Vergebung und Wohlbefinden in meinen religiösen und weltlichen Angelegenheiten, und meiner Familie und meinem Reichtum. O Allah, verhülle meine Schwächen und beruhige meine Bestürzung. O Allah, bewahre mich von vorn und von hinten und zu meiner Rechten und zu meiner Linken und von oben, und ich nehme Zuflucht bei Dir, dass ich von der Erde verschluckt werde.","title":"Dua für Vergebung und Wohlbefinden","source":"Sahih (Albani). Abu Dawud: 5074","reflection":"Bitte Allah um Vergebung, Sicherheit und Schutz in jedem Teil des Lebens mit diesem Dua, das deinen Deen, Familie, Reichtum und alle Seiten vor Schaden in dieser Welt und der nächsten abdeckt.","lesson":"Allahumma Inni As Aluka bringt Allahs Maghfirat und bedeckt alle Fehler."},{"id":104,"text":"Ich nehme Zuflucht bei Allahs perfekten Worten vor dem Übel, das Er erschaffen hat.","title":"Dua zum Schutz vor Insekten (Auzu Bikalimatillahi Tammati)","source":"Muslim: 2708, 2709","reflection":"Sage dieses Dua zum Schutz vor Insekten und allem Schaden, bitte Allah, dich sicher vor jeder bösen Sache zu halten, die Er gemacht hat, indem du Seine perfekten Worte für deine Sicherheit und Frieden nutzt.","lesson":"Auzu Bikalimatillahi Tammati hält Muslime sicher vor Insekten und verstecktem Schaden."},{"id":106,"text":"O Allah, wahrlich ich habe den Morgen erreicht und rufe Dich, die Träger Deines Thrones, Deine Engel und Deine gesamte Schöpfung an, zu bezeugen, dass Du Allah bist, keiner hat das Recht, angebetet zu werden, außer Dir, allein, ohne irgendeinen Partner und dass Muhammad Dein Diener und Gesandter ist.","title":"Mächtiges Morgendua (Allahumma Inni Asbahtu)","source":"","reflection":"Beginne deinen Tag mit diesem mächtigen Morgendua, um Iman stark zu halten, Allahs Hilfe zu suchen und Barakah und Sicherheit für dich und deine Familie bei jedem Schritt zu bringen, den du von morgens bis abends machst.","lesson":"Allahumma in diesem Dua für Morgen macht Iman frisch und hält das Herz Allah nahe."},{"id":107,"text":"O Allah, welche Segnung ich an diesem Morgen auch empfangen habe oder irgendeine Deiner Schöpfung, ist von Dir allein, ohne irgendeinen Partner, so gebührt Dir alles Lob und Dir aller Dank.","title":"Dua für den Morgen (Allahumma Ma Asbaha)","source":"","reflection":"Beginne deinen Tag mit diesem Dua am Morgen, um Allah für jede Segnung zu danken, halte dein Herz voll von Alhamdulillah und erinnere dich an Seine Geschenke mit jedem Atemzug, den du seit Sonnenaufgang nimmst.","lesson":"Allahuma in diesem Morgendua hilft Muslimen, Shukr für jede Ni’mah zu zeigen."},{"id":108,"text":"O Allah, ich bitte Dich um Wissen, das nützlich ist, und Versorgung, die gut ist, und Taten, die akzeptabel sind.","title":"Morgendua für Rizq und Wissen","source":"Sahih (Albani). Ibn Madscha: 925","reflection":"Bitte Allah mit diesem Dua für Rizq und Wissen, deinen Tag mit Halal-Reichtum, nützlichem Ilm und gutem Amal zu füllen, der Barakah bringt und dein Leben in jeder Hinsicht einfach macht.","lesson":"Allahumma in diesem Morgendua bringt reinen Rizq und macht Amal stark."},{"id":109,"text":"O Allah, wahrlich ich habe den Abend erreicht und rufe Dich, die Träger Deines Thrones, Deine Engel und Deine gesamte Schöpfung an, zu bezeugen, dass Du Allah bist, keiner hat das Recht, angebetet zu werden, außer Dir, allein, ohne irgendeinen Partner und dass Muhammad Dein Diener und Gesandter ist.","title":"Allahumma Inni Dua (Abend-Adhkar)","source":"Hasan (Ibn Baz). Abu Dawud: 5069","reflection":"Beende deinen Tag mit diesem Dua für den Abend, um Iman sicher zu halten, Allahs Einheit zu erinnern und um Seine Barmherzigkeit und Schutz zu bitten, wenn die Nacht kommt und du von deinem täglichen Amal ruhst.","lesson":"Allahuma in diesem Abenddua hält Iman stark und das Herz Allah nahe."},{"id":110,"text":"Ruhm sei Allah und Sein ist das Lob, (und) Allah, der Größte ist frei von Unvollkommenheit","title":"Bestes Dhikr und Dua (SubhanAllah wa Bihamdihi)","source":"Bukhari: 6682","reflection":"Halte deine Zunge beschäftigt mit SubhanAllah wa Bihamdihi, um Allahs Liebe zu verdienen, Sünden vergeben zu bekommen und deinen Tag mit Barakah und Frieden vom besten Dhikr und Dua im Islam zu füllen.","lesson":"Subhanallah Wa Bihamdihi Bedeutung bringt Allahs Lob und hält das Herz sauber."},{"id":112,"text":"Keiner hat das Recht, angebetet zu werden, außer Allah allein, ohne Partner, Ihm gehört alle Herrschaft und Ihm gebührt das Lob. Er gibt Leben und gibt Tod, und Er ist Ewig Lebend und stirbt nicht; in Seiner Hand ist alles Gute und Er ist fähig, alle Dinge zu tun.","title":"Dua für das Betreten des Marktes (Masnun Dua)","source":"Hasan (Albani). Tirmidhi: 3428","reflection":"Dieses Dua beim Betreten des Marktes bringt Allahs Gedenken an geschäftige Orte, hilft Muslimen, ihren Iman stark zu halten und Barakah und Sicherheit in jedem Geschäft und jeder täglichen Arbeit zu suchen.","lesson":"La Ilaha Illallahu Wahdahu La Sharika Lahu bringt riesige Barakah im Geschäft."},{"id":116,"text":"Allah! Es gibt keinen anbetungswürdigen außer Ihm, dem Ewig Lebenden, dem Einen, Der alles existierende erhält und beschützt. Weder Schlummer noch Schlaf überkommen Ihn. Ihm gehört, was in den Himmeln und was auf der Erde ist. Wer ist es, der bei Ihm Fürsprache einlegen kann, außer mit Seiner Erlaubnis? Er weiß, was ihnen in dieser Welt passiert und was ihnen im Jenseits passieren wird. Und sie werden niemals etwas von Seinem Wissen umfassen, außer dem, was Er will. Sein Thron erstreckt sich über die Himmel und die Erde, und Er empfindet keine Ermüdung beim Bewachen und Bewahren von ihnen. Und Er ist der Höchste, der Größte. (Sura Baqarah 2:255)","title":"Dua vor dem Schlafengehen (Ayatul Kursi)","source":"Al-Bukhari, Fath al-Bari 4/487, Nr. 2311","reflection":"Lass dein Herz leicht ruhen, bevor du zu Bett gehst, indem du Ayatul Kursi sagst, einen starken Vers aus Surah Baqarah, der Allahs Fürsorge, Sicherheit und Frieden in die Nacht eines jeden Muslims bringt.","lesson":"Allahs Hifazat bedeckt denjenigen, der Ayatul Kursi vor dem Zubettgehen sagt."},{"id":118,"text":"(1) Sprich: „O Ungläubige, (2) Ich bete nicht an, was ihr anbetet. (3) Noch seid ihr Anbeter dessen, was ich anbete. (4) Noch werde ich ein Anbeter dessen sein, was ihr anbetet. (5) Noch werdet ihr Anbeter dessen sein, was ich anbete. (6) Für euch ist eure Religion, und für mich ist meine Religion.“ (Sura Kafirun 109: 1-6)","title":"Dua vor dem Zubettgehen (Surah Kafirun)","source":"Sahih (Albani). Tirmidhi: 3403","reflection":"Lass dein Herz leicht ruhen, bevor du zu Bett gehst, indem du Surah Kafirun sagst, ein starkes Nacht-Dua, das deinen Iman sicher hält und jedem Muslim Allahs Hilfe und Frieden bringt.","lesson":"Surah Kafirun hält den Iman eines Muslims vor dem Schlaf rein von Shirk."},{"id":122,"text":"O Allah, in Deinem Namen sterbe ich und ich lebe.","title":"Dua zum Schlafen","source":"Bukhari: 6314","reflection":"Lass dein Herz leicht ruhen, indem du dieses Dua zum Schlafen sagst, und vertraue darauf, dass Allah dich sicher hält und dich jede Nacht und jeden Morgen mit Seiner Barakah und Barmherzigkeit aufweckt.","lesson":"Allahumma Bismika Amutu Wa Ahya bringt Frieden ins Herz vor dem Schlafengehen."},{"id":123,"text":"In Deinem Namen, O Allah, lebe ich und sterbe ich.","title":"Dua vor dem Schlaf","source":"Al-Bukhari, Fath al-Bari 11/113 Nr. 6324, Muslim 4/2083 Nr. 2711","reflection":"Lass deinen Geist und Körper ruhen, indem du dieses Dua für den Schlaf sagst, und vertraue darauf, dass Allah dir eine friedliche Nacht gibt und dich jeden Morgen mit Seiner Barmherzigkeit und Barakah aufweckt.","lesson":"Bismika Allahumma Amutu Wa Ahya hält einen Muslim während der Nacht sicher vor Schaden."},{"id":124,"text":"Lob sei Allah, Der mir Genüge gegeben hat, mich bewacht hat, mir Essen und Trinken gegeben hat, gnädig zu mir war und mir reichlich gegeben hat. Lob sei Allah in jedem Umstand. O Allah! Herr und König von allem, Gott von allem, ich suche Zuflucht bei Dir vor der Hölle.","title":"Dua zum Schlafengehen","source":"Sahih (Albani). Abu Dawud: 5058","reflection":"Zeige Dankbarkeit gegenüber Allah mit diesem Dua zum Schlafengehen, indem du Seine Geschenke erinnerst und um Seinen Schutz und Barmherzigkeit bittest, bevor du nachts ruhst.","lesson":"Alhamdulillah Ala Kulli Hal füllt das Herz mit Shukr für jede Segnung von Allah."},{"id":125,"text":"O Allah, wahrlich Du hast meine Seele erschaffen und Du sollst ihr Leben nehmen, Dir gehört ihr Leben und Tod. Wenn Du meine Seele am Leben hältst, dann beschütze sie, und wenn Du ihr Leben nimmst, dann vergib ihr. O Allah, ich bitte Dich, mir gute Gesundheit zu gewähren.","title":"Dua, um schlafen zu gehen","source":"Muslim: 2712","reflection":"Vertraue Allah deine Seele an, indem du dieses Dua machst, um schlafen zu gehen, und bitte um Seinen Schutz, Vergebung und gute Gesundheit, bevor du für die Nacht ruhst.","lesson":"Allahumma Inni Has Aluka in diesem Dua um schlafen zu gehen bringt Sicherheit für die Seele."},{"id":126,"text":"O Allah, Du bist der Erste und nichts ist vor Dir gekommen, und Du bist der Letzte, und nichts mag nach Dir kommen. Du bist der Höchste, nichts ist über Dir und Du bist der Nächste und nichts ist näher als Du. Entferne unsere Schulden von uns und bereichere uns gegen Armut.","title":"Dua zum Lesen vor dem Schlafen","source":"Muslim: 2713","reflection":"Fühle dich Allah nahe, indem du dieses Dua vor dem Schlafen sagst, und vertraue Ihm, deine Sorgen und Schulden zu entfernen und dir Barakah und Frieden zu geben, bevor du nachts ruhst.","lesson":"Allahumma in diesem Dua vor dem Schlafen erinnert einen Muslim an Allahs Größe."},{"id":127,"text":"O Allah, Herr der sieben Himmel und der Herr der Erde und Herr des Herrlichen Thrones, unser Herr und Herr aller Dinge, Spalter des Samens und des Dattelsteins, Offenbarer der Tawrah, des Injil und des Furqan, ich nehme Zuflucht bei Dir vor dem Übel aller Dinge, die Du beim Schopf ergreifen wirst. O Allah, Du bist Der Erste, also ist nichts vor Dir und Du bist Der Letzte, also ist nichts nach Dir. Du bist Ath-Dhahir, also ist nichts über Dir und Du bist Al-Batin, also ist nichts näher als Du. Begleiche unsere Schuld für uns und verschone uns vor Armut.","title":"Dua, das vor dem Schlafen gesagt werden soll","source":"Muslim: 2713, Sahih (Albani). Tirmidhi: 3481","reflection":"Lass dein Herz leicht ruhen, indem du dieses Dua machst, das vor dem Schlafen gesagt werden soll, und bitte Allah um Sicherheit, Hilfe bei Schulden und Frieden in deiner Nacht, vertrauend auf Seine Macht und Barmherzigkeit vor dem Zubettgehen.","lesson":"Allahumma in diesem Dua vor dem Schlafen bringt Barakah und Ruhe ins Herz."},{"id":128,"text":"Ich suche Zuflucht bei den perfekten Worten Allahs vor Seinem Zorn und Seiner Bestrafung, vor dem Übel Seiner Sklaven und vor den Spötteleien der Teufel und vor ihrer Anwesenheit.","title":"Dua des Schlafens","source":"Hasan (Albani). Tirmidhi: 3528","reflection":"Dieses Dua des Schlafens hilft einem Muslim, Frieden und Sicherheit in der Nacht zu finden, indem es Allah bittet, vor Schaden, Shayateen und Seinem Zorn zu schützen, bevor man mit einem ruhigen Herzen zu Bett geht.","lesson":"Audhubillah in diesem Dua für Schutz hält Allahs Zorn und Azaab fern."},{"id":129,"text":"In Deinem Namen, mein Herr, lege ich mich nieder und in Deinem Namen erstehe ich auf, wenn Du also meine Seele nehmen solltest, dann habe Erbarmen mit ihr, und wenn Du meine Seele zurückgeben solltest, dann beschütze sie in der Weise, wie Du es mit Deinen rechtschaffenen Dienern tust.","title":"Dua des Schlafs","source":"Al-Bukhari 11/126 Nr. 6320, Muslim 4/2084 Nr. 2714","reflection":"Dieses Dua des Schlafs lässt einen Muslim Allah mit seiner Seele vor dem Zubettgehen vertrauen, bittet um Seine Barmherzigkeit und Fürsorge, genau wie Er sie Seinen guten Dienern jede Nacht gibt.","lesson":"Bismika Rabbi in diesem Schlaf-Dua bringt Frieden und Sicherheit ins Herz."},{"id":130,"text":"O Allah, beschütze mich vor Deiner Bestrafung an dem Tag, an dem Deine Diener auferweckt werden.","title":"Dua vor dem Bettgehen","source":"Sahih (Albani). At-Tirmidhi: 3398","reflection":"Dieses Dua vor dem Bettgehen hilft einem Muslim, Allah um Sicherheit vor Seiner Bestrafung am Tag von Qiyamah zu bitten, was Frieden und Hoffnung vor dem Schlaf jede Nacht bringt.","lesson":"Allahumma in diesem Dua vor dem Schlaf bittet Allah, vor Azaab in Akhirah zu retten."},{"id":131,"text":"O mein Herr, ich habe in Deinem Namen geschlafen. Du vergibst meine Sünden.","title":"Dua zum Schlafen","source":"Hasan (Schu'aib al-Arnaut). Musnad Ahmad: 6620","reflection":"Dieses Dua zum Schlafen lässt einen Muslim Allah um Vergebung und Frieden bitten, bevor er zu Bett geht, vertrauend auf Seine Barmherzigkeit und Güte jede Nacht mit einem einfachen Herzen.","lesson":"Bismika Rabbi in diesem Schlaf-Dua bringt Allahs Barmherzigkeit nah ans Herz."},{"id":132,"text":"Alles Lob gebührt Allah, Der uns gespeist und uns zu trinken gegeben hat, und Der uns genügt und uns Schutz gewährt hat, denn wie viele haben niemanden, der ihnen genügt oder ihnen Schutz gewährt.","title":"Schlaf-Dua","source":"Muslim 4/2085 Nr. 2715","reflection":"Dieses Schlaf-Dua erinnert uns daran, Allah für Essen, Wasser, Schutz und Seine Fürsorge zu danken, füllt unsere Herzen mit Alhamdulillah vor dem Schlaf und lehrt uns, Allahs Barmherzigkeit jede Nacht zu vertrauen.","lesson":"Alles Lob gebührt Allah, Der uns gespeist und uns zu trinken gegeben hat, und Der uns genügt und uns Schutz gewährt hat."},{"id":134,"text":"Ich suche Zuflucht bei den perfekten Worten Allahs, die kein rechtschaffener Mensch oder Sünder überwinden kann, vor dem Übel dessen, was Er erschaffen hat, erschaffen und verbreitet hat, vor dem Übel dessen, was vom Himmel herabsteigt, vor dem Übel dessen, was zum Himmel aufsteigt. Vor dem Übel von allem, was in der Erde verstreut ist, vor dem Übel von allem, was aus der Erde herauskommt, vor dem Übel der Fitnah von Nacht und Tag, und vor dem Übel aller Fremden, außer demjenigen, der mit Güte kommt, O Barmherzigster.","title":"Duas vor dem Schlaf","source":"Sahih (Arnaut). Ahmad: 15499","reflection":"Diese Duas vor dem Schlaf helfen dir, Allah den Barmherzigsten um Sicherheit vor Schaden, Fitnah und allem Bösen zu bitten, füllen dein Herz mit Frieden und Vertrauen in Ar Rahman jede Nacht, bevor du ruhst.","lesson":"Ich suche Zuflucht bei den perfekten Worten Allahs, die kein rechtschaffener Mensch oder Sünder überwinden kann."},{"id":135,"text":"Im Namen Allahs, ich habe meine Seite für Allah niedergelegt. O Allah! Vergib meine Sünde, treibe meinen Teufel weg, befreie mich von meiner Verantwortung und platziere mich in der höchsten Versammlung.","title":"Duas vor dem Bett","source":"Sahih (Albani). Sunan Abu Dawud: 5054","reflection":"Diese Duas vor dem Bett helfen dir, Allah um Vergebung, Barakah und Sicherheit vor Shaytan zu bitten, was dein Herz ruhig und deinen Iman stark macht, bevor du jede Nacht schläfst.","lesson":"Bismillah und Allahumma bringen Frieden und Vergebung vor dem Schlaf."},{"id":136,"text":"O Allah, ich unterwerfe meine Seele Dir, und ich vertraue meine Angelegenheit Dir an, und ich wende mein Gesicht Dir zu, und ich verlasse mich vollkommen auf Dich, in Hoffnung und Furcht vor Dir. Wahrlich, es gibt keine Zuflucht noch sicheren Hafen vor Dir außer bei Dir. Ich glaube an Dein Buch, das Du offenbart hast, und an Deinen Propheten, den Du gesandt hast.","title":"Dua vor dem Bett","source":"Al-Bukhari, Fath al-Bari 11/113 Nr. 6313, Muslim 4/2081 Nr. 2710","reflection":"Dieses Dua vor dem Bett ist ein starkes Schild für dein Herz und deinen Geist, das dir hilft, Allah zu vertrauen, Frieden zu finden und um Schutz zu bitten, während du ruhst, der Sunnah folgend und jede Nacht Iman aufbauend.","lesson":"Allahumma Aslamtu Nafsi Ilaika lehrt volles Vertrauen in Allah vor dem Schlaf."},{"id":138,"text":"Es gibt keinen Anbetungswürdigen außer Allah, dem Einen, dem Siegreichen, Herr der Himmel und der Erde und allem, was zwischen ihnen ist, der Allmächtige, der Allvergebende.","title":"Dua beim Umdrehen während der Nacht","source":"Sahih nach Hakim. Imam Dhahabi 1/540; Nasa'i, Amal al-Yaum wal-Lajla Nr. 202, Ibn as-Sunni Nr. 757. Siehe auch Sahih al-Dschami 4:213","reflection":"Dieses Dua beim Umdrehen während der Nacht hilft dir, Allahs Größe zu erinnern, bringt Barakah in deinen Schlaf und hält dein Herz dem Iman nah, selbst in den ruhigsten Stunden.","lesson":"Es gibt keinen Anbetungswürdigen außer Allah, dem Einen, dem Siegreichen, Herr der Himmel und der Erde und allem, was zwischen ihnen ist, der Allmächtige, der Allvergebende."},{"id":139,"text":"Niemand hat das Recht, angebetet zu werden, außer Allah, allein, ohne Partner, Ihm gehört die Herrschaft und das Lob und Er ist zu allen Dingen fähig. Wie perfekt Allah ist, und alles Lob ist für Allah, und niemand hat das Recht, angebetet zu werden, außer Allah, Allah ist der Größte und es gibt keine Macht noch Kraft außer bei Allah, Dem Höchsten, Dem Erhabenen, O mein Herr vergib mir.","title":"Dua zum Aufwachen","source":"Sahih (Albani). Abu Dawud: 5060","reflection":"Dieses Dua zum Aufwachen füllt deinen Morgen mit Barakah, bringt dich Allah näher und hilft dir, deinen Tag mit Iman, Vergebung und dem Zikr Allahs auf deiner Zunge zu beginnen.","lesson":"Dieses Dua zu rezitieren bringt Barakah und Vergebung am Anfang des Tages."},{"id":141,"text":"Alles Lob gebührt Allah, der uns das Leben gab, nachdem Er es von uns genommen hatte, und zu Ihm ist die Auferstehung.","title":"Dua nach dem Aufwachen","source":"Al-Bukhari, vgl. Al-Asqalani, Fath al-Bari 11/113 Nr. 6314; Muslim 4/2083 Nr. 2711","reflection":"Dieses Dua nach dem Aufwachen füllt dein Herz mit Alhamdulillah, bringt Barakah in deinen Morgen und erinnert dich an Allahs Barmherzigkeit, während du einen neuen Tag mit Iman und Hoffnung auf einen guten Tag voraus beginnst.","lesson":"Dieses Dua zu rezitieren bringt Barakah und Dankbarkeit am Anfang des Tages."},{"id":142,"text":"Lob sei Allah, Der meinem Körper Kraft gab und meine Seele zu mir zurückbrachte und mir erlaubte, Seiner zu gedenken.","title":"Dua zum Aufwachen für Fajr","source":"At-Tirmidhi 5/473. Siehe Al-Albanis Sahih Tirmidhi 3/144","reflection":"Dieses Dua zum Aufwachen für Fajr füllt dein Herz mit Shukr zu Allah, dass Er dir Leben, Gesundheit und die Chance gegeben hat, Seiner zur Fajr-Zeit zu gedenken, was Barakah und Stärke in deinen Tag von Anfang an bringt.","lesson":"Dieses Dua zu rezitieren bringt Barakah und Gesundheit zu Beginn von Fajr."},{"id":144,"text":"Ich suche Zuflucht bei Allah vor dem verfluchten Satan.","title":"Dua für schlechte Träume","source":"[1] Bukhari: 7044 [2] Muslim: 6041 [3] Sahih (Albani). Tirmidhi: 2280","reflection":"Dua für schlechte Träume hilft dir, Allahs Schutz vor Shaitan zu suchen, bringt Ruhe und Sicherheit in dein Herz nach einem Albtraum und erinnert dich daran, Allahs Barmherzigkeit in jedem Moment der Angst zu vertrauen.","lesson":"Dieses Dua nach einem schlechten Traum zu rezitieren bringt Allahs Schutz vor Shaitan."},{"id":146,"text":"Alles Lob gebührt Allah, der mich mit diesem Gewand bekleidet hat und es mir versorgt hat, ohne Macht noch Kraft von mir selbst.","title":"Dua beim Anziehen von Kleidung","source":"Hasan (Albani). Abu Dawud: 4023","reflection":"Dua beim Anziehen von Kleidung erinnert dich daran, Allah für jedes Gewand zu danken, Shukr für Seinen Rizq zu zeigen und zu erinnern, dass alle Segnungen von Ihm allein kommen, nicht aus unserer eigenen Macht oder Stärke.","lesson":"Dieses Dua zu rezitieren bringt Barakah in jedes Kleid, das du trägst."},{"id":147,"text":"O Allah, für Dich ist alles Lob, Du hast mich damit bekleidet, ich bitte Dich um das Gute daran und das Gute, wofür es gemacht wurde, und ich suche Zuflucht bei Dir vor dem Übel daran und dem Übel, wofür es gemacht wurde.","title":"Dua für das Tragen neuer Kleidung","source":"Sahih (Albani). Tirmidhi: 1767","reflection":"Dua für das Tragen neuer Kleidung hilft dir, Allah für Seine Geschenke zu danken, bittet um Gutes von deinem neuen Kleid und sucht Sicherheit vor jedem Schaden, füllt dein Herz mit Shukr und Barakah jedes Mal, wenn du etwas Neues trägst.","lesson":"Dieses Dua zu rezitieren bringt Barakah und Schutz in neue Kleidung."},{"id":148,"text":"Mögest du es abnutzen und Allah (Ta'aala) ersetze es [durch ein anderes].","title":"Dua für jemanden, der neue Kleidung trägt","source":"Sahih (Albani). Abu Dawud: 4020","reflection":"Dua für jemanden, der neue Kleidung trägt, ist ein Weg, Barakah für andere zu machen, Allah bittend, ihr neues Kleid zu segnen und ihnen mehr zu geben, Herzen mit Liebe und Shukr für jedes Geschenk von Allah füllend.","lesson":"Dieses Dua zu rezitieren bringt Barakah und Glück für andere."},{"id":150,"text":"Mögest du so lange leben, dass dein Kleid abgenutzt wird.","title":"Dua für jemanden, der neue Kleidung trägt (Weiblich)","source":"Bukhari: 5993","reflection":"Dua für jemanden, der neue Kleidung trägt, ist ein Weg, Allah um langes Leben, Barakah und Glück für die Schwester oder Mutter zu bitten, ihr wünschend, ihr Kleid zu genießen, bis es alt wird mit Iman und Amal.","lesson":"Dieses Dua zu rezitieren bringt Barakah und Glück für Schwestern und Mütter."},{"id":151,"text":"Mögest du so lange leben, dass dein Kleid abgenutzt wird.","title":"Dua für jemanden, der neue Kleidung trägt (Männlich)","source":"Bukhari: 5993","reflection":"Dua für jemanden, der neue Kleidung trägt, ist ein einfacher Weg, Allah um ein langes Leben und Barakah für deinen Bruder, Vater oder Sohn zu bitten, ihm wünschend, sein neues Kleid zu genießen, bis es alt wird mit Iman und Glück.","lesson":"Dieses Dua zu rezitieren bringt Barakah und Glück für Brüder, Väter und Söhne."},{"id":152,"text":"Trage neu, lebe lobenswert und stirb als Shaheed.","title":"Dua wenn jemand neue Kleidung trägt","source":"Sahih (Albani). Ibn Madscha: 3558","reflection":"Dua neue Kleidung zu tragen bittet Allah um ein gutes Leben, Barakah und die Ehre, als Shaheed zu sterben, der Person wünschend, ihr neues Kleid mit Iman und Amal jedes Mal zu genießen, wenn sie etwas Frisches trägt.","lesson":"Dieses Dua zu rezitieren bringt Barakah und gute Wünsche für die Person, die neue Kleidung trägt."},{"id":153,"text":"Trage neu, lebe lobenswert und stirb als Shaheed und möge Allah dir jene Dinge in dieser Dunya und im Jenseits geben, die deine Augen kühlen werden.","title":"Dua, das zu jemandem gesagt wird, der neue Kleidung trägt","source":"Sahih (Albani). Sahih al-Dschami: 1234","reflection":"Dua für neue Kleidung bittet Allah, ein gutes Leben, Barakah und Kühle der Augen sowohl in der Dunya als auch in der Akhirah zu geben, der Person wünschend, ihr neues Kleid mit Iman und Glück jedes Mal zu genießen, wenn sie es trägt.","lesson":"Dieses Dua zu rezitieren bringt Barakah und Glück für die Person, die neue Kleidung trägt."},{"id":154,"text":"Im Namen Allahs, ich setze mein Vertrauen in Allah und es gibt keine Macht noch Kraft außer bei Allah.","title":"Dua für das Verlassen des Hauses","source":"Sahih (Albani). Abu Dawud: 5095","reflection":"Dua für das Verlassen des Hauses erinnert jeden Muslim daran, Allah zu vertrauen, Seine Hilfe zu suchen und um Barakah und Sicherheit zu bitten, bevor man heraustritt, jeden Weg mit Iman und Hoffnung in Allahs Fürsorge beginnend.","lesson":"Dieses Dua zu rezitieren bringt Barakah und Schutz vor dem Verlassen des Hauses."},{"id":155,"text":"Im Namen Allahs, ich setze mein Vertrauen in Allah. O Allah! Wir suchen Zuflucht bei Dir davor, unbeabsichtigt auszurutschen oder in die Irre zu gehen, oder Unterdrückung zu begehen oder unterdrückt zu werden, oder unwissend zu handeln oder unwissend behandelt zu werden.","title":"Dua vor dem Verlassen des Hauses","source":"Sahih (Albani). Tirmidhi: 3427","reflection":"Dua vor dem Verlassen des Hauses hilft Muslimen, ihren Tag mit Iman zu beginnen, Allah um Barakah, Sicherheit vor Schaden und Schutz vor Fehlern oder davor, draußen Unrecht getan zu bekommen, bittend.","lesson":"Dua vor dem Verlassen des Hauses bringt Allahs Hilfe und bedeckt dich mit Seinem Schutz."},{"id":156,"text":"O Allah, ich suche Zuflucht bei Dir, damit ich nicht in die Irre gehe oder in die Irre geführt werde, oder ausrutsche (d.h. unbeabsichtigt eine Sünde begehe) oder zu Fall gebracht werde, oder unterdrücke oder unterdrückt werde, oder mich töricht verhalte oder töricht behandelt werde.","title":"Dua beim Verlassen des Hauses","source":"Sahih (Albani). Abu Dawud: 5094","reflection":"Dieses Dua beim Verlassen des Hauses ist ein starkes Schild für Muslime, das Allah um Barakah, Sicherheit vor Fehlern und Schutz vor Schaden oder Unrecht bittet, während man mit Iman heraustritt.","lesson":"Dua beim Verlassen des Hauses schützt davor, in die Irre zu gehen oder in die Irre geführt zu werden."},{"id":157,"text":"O Allah! Ich bitte Dich um Gutes sowohl beim Eintreten als auch beim Hinausgehen; im Namen Allahs sind wir eingetreten, und im Namen Allahs sind wir hinausgegangen, und auf Allah, unseren Herrn, vertrauen wir.","title":"Dua für das Betreten des Hauses","source":"Hasan (Ibn Baz). Abu Dawud: 5096","reflection":"Dua für das Betreten des Hauses bringt Barakah und Frieden, bittet Allah um Gutes, Sicherheit und Vertrauen in Ihn jedes Mal, wenn du hineintrittst, und macht dein Haus zu einem Ort von Iman und Komfort.","lesson":"Dua für das Betreten des Hauses bringt Allahs Barakah und Sicherheit zu deinem Haus."},{"id":158,"text":"Friede sei mit euch, und die Barmherzigkeit Allahs und Seine Segnungen.","title":"Dua vor dem Betreten des Hauses","source":"Hasan (Ibn Hadschar). Mischkat: 4/316","reflection":"Bringe Frieden und Barakah in dein Haus, indem du dieses Dua vor dem Betreten des Hauses sagst, damit Allahs Barmherzigkeit und Segnungen deine Familie füllen und jeden darin vor Schaden und Ärger schützen.","lesson":"Assalamualaikum Warahmatullahi Wabarakatuh zu sagen bringt Allahs Barakah zum Heim."},{"id":159,"text":"Im Namen Allahs treten wir ein und im Namen Allahs gehen wir hinaus, und auf Allah, unseren Herrn, setzen wir unser Vertrauen.","title":"Dua des Betretens des Hauses","source":"[1] Hasan (Ibn Baz). Abu Dawud: 5096 [2] Muslim: 2018","reflection":"Lass dein Haus mit Allahs Fürsorge und Vertrauen gefüllt sein, indem du dieses Dua des Betretens des Hauses sagst, jeden Schritt hinein und hinaus sicher mit Seinem Namen machend und deine Familie nah an Seiner Rahmah haltend.","lesson":"Bismillah in diesem Dua für das Betreten des Hauses hält Shaytan von deinem Haus fern."},{"id":160,"text":"Im Namen Allahs. O Allah, ich suche Schutz bei Dir vor den männlichen und weiblichen unreinen Geistern.","title":"Dua vor dem Betreten der Toilette","source":"Bukhari: 142","reflection":"Halte dich sicher vor Schaden und Unreinheit, indem du dieses Dua vor dem Betreten der Toilette sagst, damit Allahs Name dich vor allem Bösen schützt und dein Herz rein und voll von Iman hält.","lesson":"Bismillah in diesem Dua vor dem Betreten der Toilette hält Shayateen von dir fern."},{"id":163,"text":"Ich bezeuge, dass niemand das Recht hat, angebetet zu werden außer Allah, allein, ohne Partner, und dass Muhammad Sein Sklave und Gesandter (ﷺ) ist. Ich bin zufrieden mit Allah als einem Herrn, und Muhammad als einem Gesandten und Islam als einer Religion.","title":"Dua nach dem Hören des Adhan (Azan Dua)","source":"Muslim: 386","reflection":"Lass deinen Iman stark wachsen, indem du das Azan Dua nach dem Hören des Gebetsrufs sagst, Liebe für Allah, Seinen Gesandten und Islam zeigend, und Barakah zu deinem Salah und täglichen Amal bringend.","lesson":"Ash Hadu Allah Ilaha Illallah im Azan Dua lässt Iman im Herzen scheinen."},{"id":164,"text":"O Allah, gewähre Muhammad (ﷺ) Deine Gunst und der Familie von Muhammad (ﷺ), wie Du Ibrahim (AS) und der Familie von Ibrahim (AS) Deine Gunst gewährt hast. Du bist preiswürdig, höchst glorreich. O Allah, segne Muhammad (ﷺ) und die Familie von Muhammad (ﷺ), wie Du Ibrahim und die Familie von Ibrahim (AS) gesegnet hast. Du bist preiswürdig, höchst glorreich.","title":"Dua nach dem Adhan (Durood Sharif)","source":"Muslim: 384","reflection":"Dieses Dua nach Azan bringt Segnungen und Barmherzigkeit von Allah, den Rang des Propheten Muhammad ﷺ und seiner Familie erhöhend, und bringt Barakah zu denen, die Durood Sharif nach dem Hören des Gebetsrufs senden.","lesson":"Allah gibt Barakah demjenigen, der Durood Sharif nach Azan sendet."},{"id":165,"text":"O Allah, Besitzer dieses perfekten Rufes und Besitzer dieses Gebets, das verrichtet werden soll, gewähre Muhammad (ﷺ) Al-Waseelah und Al-Fadeelah und erhebe ihn auf eine gepriesene Plattform, die Du ihm versprochen hast.","title":"Dua nach dem Adhan (Azan Dua)","source":"Bukhari: 614","reflection":"Dieses Dua nach Adhan bringt besondere Belohnungen, hilft, den Rang des Propheten Muhammad ﷺ zu erhöhen, und bringt Barakah und Akzeptanz für jene, die Allah erinnern, nachdem sie den Azan gehört haben.","lesson":"Allah gewährt das Versprechen von Maqam Mahmood an Prophet Muhammad ﷺ."},{"id":168,"text":"O Allah, leite die Imame und vergib den Muezzinen.","title":"Dua für Imame und Muezzine (Dua für Vergebung)","source":"Sahih (Albani). Abu Dawud: 517","reflection":"Dieses Dua für Imame und Muezzine bringt Allahs Führung für Anführer und Vergebung für jene, die zum Gebet rufen, die Masjid zu einem Ort von Barakah und Einheit für alle Muslime machend.","lesson":"Allahumma gibt Hidayah an Imame, damit sie Salah mit wahrem Iman führen."},{"id":171,"text":"O Allah, mache mich zu einem derjenigen, die sich Dir reuig zuwenden, und mache mich zu einem derjenigen, die gereinigt sind.","title":"Nach Wudu Dua (Gebetswaschung)","source":"Sahih (Albani). Tirmidhi: 55","reflection":"Dieses Dua nach Wudu bringt einen Muslim näher zu Allah, indem man um Vergebung und Reinheit bittet, was jede Waschung zu einer Chance macht, Barakah zu verdienen und das Herz sauber für Salah und Amal zu halten.","lesson":"Allahumma in diesem Dua nach Wudu hilft einem Muslim, Barakah in jedem Salah zu bekommen."},{"id":172,"text":"Ehre sei Dir, O Allah, und Lob; ich bezeuge, dass es niemanden anbetungswürdigen gibt außer Dir. Ich suche Deine Vergebung und wende mich Dir in Reue zu.","title":"Dua nach der Waschung (Wudu Dua)","source":"An-Nasa'i, 'Amal al-Yaum wal-Lajla, S. 173. Siehe auch Al-Albani, Irwa' al-Ghalil 1/135 und 2/94.","reflection":"Dieses Dua nach der Waschung hilft einem Muslim, Allahs Größe zu erinnern und um Vergebung zu bitten, was jedes Wudu zu einer Zeit macht, das Herz zu reinigen und sich für Salah mit Barakah und Iman bereit zu machen.","lesson":"Subhanaka Allahumma Wa Bihamdika in diesem Dua nach Waschung bringt Barakah."},{"id":173,"text":"O Allah, platziere in meinem Herzen Licht, und auf meiner Zunge Licht, und in meinen Ohren Licht, und in meinen Augen Licht, und platziere hinter mir Licht, und vor mir Licht, und über mir Licht, und unter mir Licht. O Allah, gewähre mir Licht.","title":"Dua für den Gang zur Moschee (Dua e Noor)","source":"Bukhari: 6316","reflection":"Dieses Dua für den Gang zur Moschee füllt das Herz und Leben eines Muslims mit Allahs Noor, jeden Schritt zur Masjid zu einem Weg machend, Barakah, Licht und Segnungen in Amal und Iman zu bekommen.","lesson":"Allahumma im Dua E Noor bringt Licht zum Herzen und lässt Amal hell scheinen."},{"id":174,"text":"O Allah, platziere Licht in meinem Herzen, und auf meiner Zunge Licht, und in meinen Ohren Licht und in meiner Sicht Licht, und über mir Licht, und unter mir Licht, und zu meiner Rechten Licht, und zu meiner Linken Licht, und vor mir Licht und hinter mir Licht. Platziere in meiner Seele Licht. Vergrößere für mich Licht, und vermehre für mich Licht. Mache für mich Licht und mache mich zu einem Licht. O Allah, gewähre mir Licht, und platziere Licht in meinen Nerven, und in meinem Körper Licht und in meinem Blut Licht und in meinem Haar Licht und in meiner Haut Licht.","title":"Dua für den Gang zur Masjid","source":"Bukhari: 6316","reflection":"Dieses Dua für den Gang zur Masjid füllt das Herz, den Körper und die Seele eines Muslims mit Allahs Noor, jeden Schritt zur Moschee zu einem Weg machend, Barakah, Licht und Segnungen in Amal und Iman zu bekommen.","lesson":"Allahumma im Dua des Lichts bringt Noor zu jedem Teil des Körpers und Herzens."},{"id":175,"text":"Im Namen Allahs, Und Segnungen und Frieden seien auf dem Gesandten Allahs (ﷺ). O Allah, öffne vor mir die Türen Deiner Barmherzigkeit.","title":"Dua beim Betreten der Masjid (Wassalatu Wassalamu)","source":"Sahih (Albani). Abu Dawud: 465, Muslim: 713","reflection":"Dieses Dua beim Betreten der Masjid bringt einen Muslim unter Allahs Barmherzigkeit und Segnungen, jeden Schritt innerhalb der Moschee zu einem Weg machend, Barakah, Frieden und Nähe zu Rasulullah (Friede sei mit ihm) zu bekommen.","lesson":"Bismillah im Dua für das Betreten der Masjid bringt Barakah und Sicherheit bei jedem Schritt."},{"id":176,"text":"Im Namen Allahs, Ya Allah, bitte sende Segnungen und Frieden auf den Gesandten Allahs (ﷺ). O Allah, öffne vor mir die Türen Deiner Barmherzigkeit.","title":"Dua für das Betreten der Moschee (Allahumma Salli Ala Muhammad)","source":"Hasan (Albani). Ibn as-Sunni: 88, Muslim: 713","reflection":"Die Moschee mit diesem Dua zu betreten bringt Allahs Barmherzigkeit näher, hilft, dein Herz sauber zu halten, und erinnert dich daran, den Propheten Muhammad ﷺ jedes Mal zu ehren, wenn du hineintrittst.","lesson":"Allahumma Salli Ala Muhammad in diesem Dua für das Betreten der Moschee bringt Barakah."},{"id":177,"text":"O Allah, vergib mir meine Sünden und öffne mir die Tore Deiner Barmherzigkeit.","title":"Dua zum Betreten der Moschee (Rabbighfirli dhunubi)","source":"Sahih (Albani). Ibn Madscha: 771","reflection":"Dieses Dua zum Betreten der Moschee bittet Allah um Vergebung und Barmherzigkeit, dein Herz für Salah bereit machend und dir helfend, deine Zeit in der Masjid mit einer sauberen Seele und Hoffnung auf Barakah zu beginnen.","lesson":"Rabbighfirli im Dua vor dem Betreten der Moschee bringt Allahs Maghfirat näher."},{"id":178,"text":"Ich nehme Zuflucht bei Allah, Dem Höchsten und bei Seinem Edlen Angesicht, und Seiner ewigen Autorität vor dem verfluchten Teufel. Im Namen Allahs, und Gebete und Friede seien auf dem Gesandten Allahs (ﷺ). O Allah, öffne die Tore Deiner Barmherzigkeit für mich.","title":"Dua vor dem Betreten der Moschee (Auzubillah)","source":"Sahih (Albani). Abu Dawud: 465, 466","reflection":"Dieses Dua vor dem Betreten der Moschee hält Shaitan fern, bringt Allahs Barmherzigkeit und hilft dir, deine Zeit in der Masjid mit einem sauberen Herzen und Liebe für den Propheten ﷺ zu beginnen.","lesson":"Auzubillah im Dua Moschee Betreten gibt starke Hifazat vor Shaitans Waswasah."},{"id":179,"text":"Im Namen Allahs (gehe ich hinaus). Oh Allah! Bitte sende Segnungen und Frieden auf Muhammad (ﷺ). Oh Allah! Ich will von Deiner Fülle.","title":"Dua für das Verlassen der Masjid (Allahumma Inni As Aluka)","source":"Hasan (Albani). Ibn as-Sunni: 88, Muslim: 713","reflection":"Dieses Dua für das Verlassen der Masjid bittet Allah um Seine Fülle, hält den Propheten ﷺ in deinem Herzen und hilft dir, mit Barakah und Hoffnung auf mehr gute Taten in deinem täglichen Leben herauszutreten.","lesson":"Allahumma Inni As Aluka im Dua beim Verlassen der Masjid bringt Allahs Fazl in den täglichen Amal."},{"id":180,"text":"Im Namen Allahs, und Frieden und Segnungen seien auf dem Gesandten Allahs (ﷺ). O Allah, ich bitte um Deine Gunst, O Allah, beschütze mich vor Satan dem Verstoßenen.","title":"Dua beim Verlassen der Masjid (Wassalatu Wassalamu)","source":"Sahih (Albani). Ibn Madscha: 773","reflection":"Dieses Dua beim Verlassen der Masjid bittet Allah um Seine Gunst, hält Shaitan fern und hilft dir, mit Frieden herauszutreten, den Propheten ﷺ erinnernd und Barakah in deinem täglichen Amal haltend.","lesson":"Bismillah im Dua für das Verlassen der Moschee hält Iman sicher und Amal stark draußen."},{"id":181,"text":"O Allah, beschütze mich vor Satan dem Verstoßenen.","title":"Dua beim Verlassen der Moschee (Allahumma Ajirni)","source":"Sahih (Ibn Hibban). Ibn Hibban: 2047","reflection":"Während du aus der Masjid heraustrittst, hält dieses Dua dich sicher vor Shaitans Tricks und bringt Allahs Hilfe, deinen Heimweg und dein tägliches Leben mit Seinem Barakah und Seiner Fürsorge gefüllt machend.","lesson":"Allahumma Ajirni Minannar hält einen Muslim sicher vor Shaitans Waswasah."},{"id":182,"text":"O Allah, beschütze mich vor Satan dem Verstoßenen.","title":"Moschee Verlassen Dua","source":"Sahih (Albani). Ibn Madscha: 773","reflection":"Wenn ein Muslim die Masjid verlässt, bittet dieses Dua Allah, Shaitan fernzuhalten, und bringt Frieden, jeden Schritt draußen mit Seiner Fürsorge und Sicherheit für den kommenden Tag gefüllt machend.","lesson":"Allahumma hält das Herz sicher vor Shaitans Übel nach dem Verlassen der Moschee."},{"id":183,"text":"O Herr verzeihe meine Sünden, und öffne die Tore Deiner Segnungen für mich.","title":"Masjid Verlassen Dua (Allahummaghfirli)","source":"Sahih (Albani). Ibn Madscha: 771","reflection":"Während du aus der Masjid heraustrittst, bittet dieses Dua Allah um Vergebung und Seine Gaben, deinen Tag heller machend mit Barakah, Barmherzigkeit und Türen der Güte, die sich für dich öffnen.","lesson":"Allahummaghfirli hilft einem Muslim, Vergebung für Sünden nach Salah zu bekommen."},{"id":184,"text":"Möge Allah es dir nicht zurückgeben.","title":"Dua für denjenigen, der verlorene Gegenstände in der Moschee ankündigt","source":"Sahih (Albani). Tirmidhi: 1321","reflection":"Dieses Moschee Dua lehrt Respekt für Allahs Haus und hält die Masjid friedlich, Muslime erinnernd, dem richtigen Weg zu folgen, wenn etwas in der Moschee verloren ist oder fehlt.","lesson":"Moschee Dua hilft, die Masjid sicher vor lauten Rufen über Verlorenes und Gefundenes zu halten."},{"id":185,"text":"Möge Allah deinem Geschäft keinen Profit geben.","title":"Dua für die Person, die in der Moschee handelt","source":"Sahih (Albani). Tirmidhi: 1321","reflection":"Dieses Masjid Dua erinnert Muslime daran, die Moschee rein für Salah und Zikr Allah zu halten, den richtigen Weg lehrend, Allahs Haus zu respektieren und Geschäfte außerhalb seiner Türen zu halten.","lesson":"Masjid Dua hilft Muslimen, sich zu erinnern, Geschäft nicht mit Salah und Amal zu mischen."},{"id":187,"text":"O Allah! Trenne mich von meinen Sünden wie Du den Osten vom Westen getrennt hast. O Allah, reinige mich von meinen Übertretungen wie das weiße Gewand von Flecken gereinigt wird. O Allah! Wasche meine Sünden weg mit Eis und Wasser und Frost.","title":"Dua nach Takbeer im Salah","source":"Bukhari: 744","reflection":"Dieses Dua nach Takbeer im Salah hilft einem Muslim, das Gebet mit einem sauberen Herzen zu beginnen, Allah bittend, Sünden weit fernzuhalten und jedes Namaz rein und voll von Barakah und Vergebung zu machen.","lesson":"Allahumma Baid im Dua Al Istiftah hält Sünden fern wie Osten und Westen im Namaz."},{"id":188,"text":"O Allah, Herr von Jibra-eel, Meeka-eel und Israfeel (große Engel), Schöpfer der Himmel und der Erde, Kenner des Gesehene und des Ungesehene. Du bist der Schlichter zwischen Deinen Dienern in dem, worin sie gestritten haben. Leite mich zur Wahrheit durch Deine Erlaubnis, in dem, worin sie abgewichen sind, denn wahrlich, Du leitest wen Du willst auf einen geraden Pfad.","title":"Dua beim Beginn des Tahajjud-Gebets","source":"Muslim: 770","reflection":"Dieses Dua für Tahajjud-Gebet vor Salah bringt einen Muslim näher zu Allah, das Herz mit Barakah und Iman füllend, und hilft, zu Sirat Al Mustaqim in der Stille der Nacht zu leiten.","lesson":"Allah gibt Barakah demjenigen, der dieses Dua für Tahajjud-Gebet macht."},{"id":190,"text":"O Allah, Du bist der Herrscher, niemand hat das Recht, angebetet zu werden außer Dir. Du bist mein Herr und ich bin Dein Diener, ich habe meiner eigenen Seele Unrecht getan und habe meine Sünde anerkannt, also vergib mir alle meine Sünden, denn niemand vergibt Sünden außer Dir. Leite mich zu den besten Charaktereigenschaften, denn niemand kann dazu leiten außer Dir, und befreie mich von den schlechtesten Charaktereigenschaften, denn niemand kann mich davon befreien außer Dir.","title":"Dua beim Tahajjud (Am Anfang)","source":"Muslim: 771","reflection":"Dieses Dua beim Tahajjud hilft einem Muslim, Allah um Vergebung und guten Charakter zu bitten, das Nachtgebet gesegneter und voll von Hoffnung machend für jene, die Allahs Barmherzigkeit und Führung suchen.","lesson":"Allahumma in diesem Dua beim Tahajjud bringt wahre Reue im Islam zum Herzen."},{"id":191,"text":"Hier bin ich, in Antwort auf Deinen Ruf, glücklich, Dir zu dienen. Alles Gute ist in Deinen Händen und Übel stammt nicht von Dir. Ich existiere durch Deinen Willen und werde zu Dir zurückkehren. Gesegnet und Hoch bist Du, ich suche Deine Vergebung und bereue vor Dir.","title":"Dua zu Beginn des Gebets (nach Takbir)","source":"Muslim: 771","reflection":"Dieses Dua vor Salat nach Takbir erinnert einen Muslim daran, Salah mit einem sauberen Herzen zu beginnen, Allahs Vergebung und Barakah vor jedem Gebet für besseres Amal und Iman suchend.","lesson":"Dua vor Salat hilft Muslimen, Salah mit Istighfar und reiner Niyyah zu beginnen."},{"id":192,"text":"Allah ist der Größte, der Allergrößte. Allah ist der Größte, der Allergrößte. Allah ist der Größte, der Allergrößte. Lob sei Allah, reichlich. Lob sei Allah, reichlich. Lob sei Allah, reichlich. Ruhm sei Allah, am Anbruch des Tages und an seinem Ende.","title":"Dua zu Beginn des Salah (Allahu Akbar Kabira)","source":"Hasan li ghairihi (Schu'aib al-Arnaut). Abu Dawud: 764","reflection":"Dieses Vor Namaz Dua mit Allahu Akbar Kabira füllt das Herz mit Lob und Dank, einem Muslim helfend, Salah mit starkem Iman und Barakah vom ersten Takbir bis zum letzten zu beginnen.","lesson":"Allahu Akbar im Dua vor Salah hebt das Herz mit Lob und wahrem Tawheed."},{"id":195,"text":"Ruhm sei meinem Herrn, dem Erhabenen.","title":"Dua im Ruku (Subhana Rabbiyal Azeem)","source":"Sahih (Albani). Tirmidhi: 262","reflection":"Dieses Dua im Ruku bringt einen Muslim näher zu Allah, Respekt und Lob zeigend, und hilft, das Herz demütig während jedem Schritt von Salah und muslimischem Gebet zu halten.","lesson":"Subhana Rabbiyal Azeem im Ruku zeigt wahren Respekt für Allahs Größe."},{"id":196,"text":"Ruhm und Lob seien meinem mächtigen Herrn.","title":"Dua für Ruku (Subhana Rabbiyal Adheem Wa Bihamdihi)","source":"Hasan Sanad (Schu'aib al-Arnaut). Abu Dawud: 870","reflection":"Dieses Dua für Ruku hilft einem Muslim, Allah mit sowohl Worten als auch Herz zu preisen, jedes Ruku im Salah bedeutungsvoller und voll von Barakah für jene machend, die der Sunnah folgen.","lesson":"Subhana Rabbiyal Azeem Wa Bihamdihi im Ruku bringt doppelte Belohnung und Lob."},{"id":197,"text":"Ruhm (sei Dir), Allerheiligster (bist Du), Herr der Engel und des Geistes.","title":"Dua im Ruku (Subbuhun Quddusun Rabbul Mala Ikati War Ruh)","source":"Sahih (Albani). Abu Dawud: 872","reflection":"Dieses Ruku Dua hilft einem Muslim, Allah als den Herrn der Engel und des Geistes zu preisen, jedes Ruku im Salah besonderer und voll von Respekt für Allahs Größe machend.","lesson":"Subbuhun Quddusun im Ruku zeigt tiefen Respekt für Allahs reine und heilige Namen."},{"id":198,"text":"O Allah, vor Dir verbeuge ich mich (im Gebet) und an Dich glaube ich und Dir habe ich mich unterworfen. Vor Dir ist mein Gehör gedemütigt, wie auch mein Augenlicht, mein Verstand, meine Knochen, meine Nerven.","title":"Dua für Ruku (Allahumma Laka Rakatu Wa Bika Amantu)","source":"Sahih (Albani). Abu Dawud: 760","reflection":"Dieses Dua für Ruku hilft einem Muslim, volles Vertrauen und Hingabe an Allah zu zeigen, jedes Ruku im Salah zu einer Zeit von wahrem Glauben und Respekt für den Schöpfer in jedem Teil des Körpers machend.","lesson":"Allahumma Laka Rakatu im Ruku zeigt volles Amal und Vertrauen in Allahs Macht."},{"id":199,"text":"Ruhm sei Dir, Meister der Macht, der Herrschaft, der Majestät und Größe.","title":"Dua im Ruku","source":"Sahih (Albani). Abu Dawud: 873","reflection":"Dieses Dua im Ruku hilft einem Muslim, Allahs Macht und Größe zu preisen, jedes Ruku im Salah zu einer Zeit machend, Allahs Kontrolle über alle Dinge und Seinen hohen Status zu erinnern.","lesson":"Subhaana Dhil-Jabarooti im Ruku zeigt wahres Lob für Allahs Macht und Herrschaft."},{"id":200,"text":"Ruhm ist Dir, O Allah, und Lob. Ich bitte dich um Vergebung und ich wende mich dir zu (vom Sündigen).","title":"Dua im Rukoo (Subhanaka wa Bihamdika Astaghfiruka)","source":"Hasan (Albani). Silsila Sahiha: 3032","reflection":"Dieses Ruku Dua bringt einen Muslim näher zu Allahs Barmherzigkeit und Vergebung, jedes Ruku im Salah zu einer Zeit für Lob, Reue und Suchen von Barakah vom Allvergebenden machend.","lesson":"Allah vergibt Sünden, wenn ein Muslim Ruku Dua mit einem Herzen voll von Iman sagt."},{"id":201,"text":"Gepriesen bist Du, O Allah, unser Herr, und Lob gebührt Dir. O Allah, vergib mir. [1]","title":"Dua im Ruku (Dua um Vergebung)","source":"[1] Bukhari: 794 [2] Sure An-Nasr 110:3","reflection":"Dieses Dua im Ruku bringt einen Muslim näher zu Allahs Barmherzigkeit und Vergebung, hilft den Herzen, demütig und rein zu bleiben, während man sich im Salah verbeugt, und bittet um Allahs Güte und Barakah in jedem Gebet.","lesson":"Allahs Barmherzigkeit kommt nahe, wenn ein Muslim subhanakallahumma im Ruku sagt."},{"id":202,"text":"Allah hört denjenigen, der Ihn preist.","title":"Dua nach dem Ruku (Sami Allahu Liman Hamidah)","source":"Bukhari: 796","reflection":"Dieses Dua nach dem Ruku erinnert Muslime daran, dass Allah jedes Wort des Lobes hört, was das Salah bedeutungsvoller macht und das Herz mit Dankbarkeit und Hoffnung auf Allahs Barakah und Güte füllt.","lesson":"Allah hört dem zu, der nach dem Ruku Sami Allahu Liman Hamidah sagt."},{"id":203,"text":"O Allah, unser Rabb (Herr), Dir gehört das Lob in allen Himmeln und der ganzen Erde und allem, was Du danach (zu erschaffen) wünschst. O Du, Der würdig des Lobes und des Ruhms ist, am würdigsten dessen, was ein Diener sagt - und wir alle sind Deine Diener: Niemand kann zurückhalten, was Du gibst, oder geben, was Du zurückhältst, und Reichtum kann einem wohlhabenden Menschen nicht gegen Dich nützen.","title":"Dua nach dem Ruku (Allahumma Rabbana Wa Lakal-Hamd)","source":"Muslim: 477","reflection":"Dieses Dua nach dem Ruku füllt das Herz mit Lob für Allah, erinnert Muslime daran, dass alle Macht und Gaben allein von Ihm kommen, und bringt Barakah und Dankbarkeit in jedes Salah und tägliche Amal.","lesson":"Allahs Gaben und Barakah erreichen denjenigen, der Rabbana lakal hamd nach dem Ruku sagt."},{"id":204,"text":"[1] Unser Herr, Dir gebührt das Lob. [2] O Allah, unser Herr, Dir gebührt das Lob.","title":"Rabbana Lakal Hamd (Dua nach dem Ruku)","source":"Bukhari: 796","reflection":"Dieses kurze Dua nach dem Ruku füllt das Salah mit Dankbarkeit, hilft Muslimen, sich an Allahs Gaben zu erinnern, und macht jedes Gebet voller Barakah und Iman für diejenigen, die es mit wahrem Herzen sagen.","lesson":"Allahs Lob wächst im Herzen, wenn ein Muslim Rabbana lakal hamd nach dem Ruku sagt."},{"id":207,"text":"Lob gebührt Dir, O Allah, unser Herr! Lob gebührt Dir, es füllt die Himmel, füllt die Erde, vervollständigt alles, was zwischen ihnen ist, und dann vervollständigt es, was immer Du willst.","title":"Dua nach dem Aufrichten aus dem Ruku","source":"Muslim: 476","reflection":"Dieses Dua nach dem Ruku füllt dein Herz mit Lob für Allah, macht dein Salah vollständiger und bringt jedes Mal mehr Segen, wenn du dich im Gebet aus der Verbeugung aufrichtest.","lesson":"Allahumma rabbana Dua nach dem Ruku bringt mehr Barakah in jedes muslimische Gebet."},{"id":208,"text":"Allah! Unser Herr, Dir gebührt das Lob, das die Himmel und die Erde füllen würde und das, was zwischen ihnen ist, und das, was Dir daneben gefallen wird. Würdig bist Du allen Lobes und Ruhms. Niemand kann zurückhalten, was Du gibst, oder geben, was Du zurückhältst. Und die Größe, O! Das Große nützt nichts gegen Dich.","title":"Dua beim Aufrichten aus dem Ruku Nr. 2","source":"Muslim: 478","reflection":"Dieses Dua nach dem Ruku erinnert uns daran, dass nur Allah gibt und nimmt, was unsere Gebete mit Lob und Vertrauen füllt und jedes muslimische Gebet gesegneter und von Allah akzeptierter macht.","lesson":"Allahumma rabbana Dua nach dem Ruku zeigt volles Vertrauen in Allahs Macht und Gaben."},{"id":209,"text":"Lob gebührt Allah, vieles gute und gesegnete Lob, wie es unser Herr liebt und womit Er zufrieden ist","title":"Dua zum Preisen Allahs (Dua nach dem Ruku)","source":"Hasan (Albani). Sunan Nasa'i: 931","reflection":"Dieses Dua nach dem Ruku füllt dein Gebet mit Worten, die Allah liebt, bringt mehr Barakah und macht deine Salah-Schritte wohlgefälliger für Ihn, jedes Mal wenn du Ihn im Namaz preist.","lesson":"Alhamdu lillahi Dua nach dem Ruku bringt Lob, das Allah liebt und akzeptiert."},{"id":213,"text":"Ruhm sei meinem Herrn, dem Höchsten.","title":"Dua im Sujood (Subhana Rabbiyal Ala)","source":"Muslim: 772","reflection":"Dieses Dua im Sujood bringt dich Allah näher, füllt deine Sajdah mit Lob und macht dein Salah beliebter bei Allah, jedes Mal wenn du Subhana Rabbiyal Ala im Gebet sagst.","lesson":"Subhana Rabbiyal Ala im Sujood bringt mehr Barakah und Frieden in jede Sajdah."},{"id":214,"text":"Ruhm und Lob sei meinem höchsten Herrn.","title":"Dua für Sajda (Sajda Dua)","source":"Hasan Sanad (Schu'aib al-Arnaut). Abu Dawud: 870","reflection":"Spüre die Nähe zu Allah und hebe deinen Iman, indem du Sajda Dua in jedem Sujood sagst, da dieses kurze Gebet Segen und Frieden in das Herz jedes Muslims bringt.","lesson":"Subhana Rabbiyal Ala im Sujood bringt Barakah und macht Salah akzeptierter."},{"id":215,"text":"O Allah, vergib mir alle meine Sünden, die großen und die kleinen, die ersten und die letzten, jene, die offensichtlich sind und jene, die verborgen sind.","title":"Dua für Sujood (Allahumma Maghfir Lee)","source":"Muslim: 483","reflection":"Bitte Allah um volle Vergebung in jedem Sujood mit diesem kraftvollen Dua, das dein Herz Frieden und Hoffnung finden lässt, während du um Barmherzigkeit und eine reine Aufzeichnung der Taten betest.","lesson":"Allahummaghfirli zambi im Sujood hilft, alle Arten von Sünden für Muslime wegzuwischen."},{"id":216,"text":"O Allah, ich suche Schutz in Deiner Zufriedenheit vor Deinem Zorn, und ich suche Schutz in Deiner Vergebung vor Deiner Bestrafung. Ich suche Schutz bei Dir vor Dir. Ich kann Dein Lob nicht zählen. Du bist so, wie Du Dich selbst gepriesen hast.","title":"Dua nach dem Ruku (Bittgebet beim Aufrichten aus der Verbeugung)","source":"Muslim: 486, Sahih (Albani). Tirmidhi: 3566","reflection":"Finde Frieden und Hoffnung, indem du dieses Dua nach dem Ruku sagst, da es Allahs Barmherzigkeit bringt, das Herz demütig hält und jedem Muslim hilft, sicher vor Zorn und Bestrafung zu bleiben.","lesson":"Allahumma inni im Ruku-Dua bringt Allahs Zufriedenheit und hält Seinen Zorn fern."},{"id":217,"text":"O Allah, platziere Licht in mein Herz, und in meine Ohren Licht und in meine Sicht Licht, und zu meiner Rechten Licht, und zu meiner Linken Licht, und vor mir Licht und hinter mir Licht, und über mir Licht, und unter mir Licht. O Allah, mache für mich Licht, und mache mich zu einem Licht, und platziere Licht in meine Seele, und platziere Licht in meine Nerven, und in mein Fleisch Licht und in mein Blut Licht und in mein Haar Licht und in meine Haut Licht. O Allah, gewähre mir Licht.","title":"Dua beim Aufrichten aus dem Ruku (Dua Noor)","source":"Sahih Bukhari: 6316, Sahih Muslim: 763","reflection":"Bitte Allah um Noor in jedem Teil des Lebens mit diesem Dua nach dem Ruku, damit dein Herz und deine Handlungen hell mit Seinem Licht und Seiner Führung bei jedem Schritt, den du machst, leuchten.","lesson":"Dua für Licht füllt das Herz und das Gesicht mit Noor und bringt Frieden im Amal."},{"id":220,"text":"O Allah, vor Dir werfe ich mich nieder, Dir habe ich mich ergeben, und an Dich glaube ich. Mein Gesicht ist niedergeworfen vor Dem, Der es erschaffen hat, es geformt hat und ihm Gehör und Sicht gegeben hat. Gesegnet ist Allah, der Beste der Schöpfer.","title":"Dua im Sujood (Allaahumma Laka Sajadtu wa Laka Aslamtu)","source":"Sahih (Albani). Nasa'i: 1126","reflection":"Dieses Dua für Sujood hilft einem Muslim, volles Vertrauen in Allah zu zeigen, was jede Niederwerfung im Salah bedeutungsvoller macht und das Herz mit Dankbarkeit für Seine Gaben und Barmherzigkeit füllt.","lesson":"Allahumma im Sujood zeigt das volle Amal und Vertrauen eines Muslims in Allahs Plan."},{"id":222,"text":"O Mein Herr, vergib mir. Mein Herr, vergib mir.","title":"Dua zwischen zwei Sujud","source":"Sahih (Albani). Abu Dawud: 874","reflection":"Dieses Dua zwischen zwei Sujud hilft einem Muslim, Allah um Vergebung zu bitten, macht Salah weicher und füllt das Herz mit Hoffnung auf Barmherzigkeit und eine reine Aufzeichnung der Taten.","lesson":"Rabbighfirli Dua bringt Allahs Vergebung nahe und wischt kleine Sünden weg."},{"id":223,"text":"O Allah! Verzeihe mir, habe Barmherzigkeit mit mir, leite mich und gewähre mir Versorgung.","title":"Dua zwischen Sujud (Allahummaghfirli Warhamni Wahdini Warzuqni)","source":"Sahih (Albani). Tirmidhi: 284, Hasan (Albani). Abu Dawud: 850","reflection":"Dieses Dua zwischen zwei Sujud hilft einem Muslim, Allah um Vergebung, Barmherzigkeit, Gesundheit, Führung und Rizq zu bitten, was jedes Salah voller Hoffnung und Barakah von Allah macht.","lesson":"Allahummaghfirli Dua bringt Allahs Maghfirat und bedeckt das Herz mit Seiner Barmherzigkeit."},{"id":225,"text":"O Allah, schreibe es als Belohnung für mich auf, und erlöse mich dafür von einer Sünde, und mache es zu einem Schatz für mich im Paradies. Nimm es von mir an, wie Du es von Deinem Diener Dawud angenommen hast.","title":"Dua für Sajdah im Koran","source":"Hasan (Albani). Tirmidhi: 579","reflection":"Dieses Dua für Sujood nach Ayat Sajadah im Koran bringt Belohnung, entfernt Sünden und hilft einem Muslim, Nähe zu Allah zu erlangen, was jede Sajdah im Tilawat e Quran bedeutungsvoller und akzeptierter macht.","lesson":"Allah gibt Belohnung für jede Sajdah in der Koranrezitation mit diesem Dua für Sujood."},{"id":226,"text":"Ich habe mein Gesicht vor Dem niedergeworfen, Der es erschaffen hat, und ihm Gehör und Sicht durch Seine Macht und Seine Kraft gegeben hat.","title":"Sajdah-Dua für Nachtrezitation","source":"Hasan (Albani). Tirmidhi: 580","reflection":"Dieses Sajdah-Dua für Sujood im Tahajjud-Gebet hilft einem Muslim, sich an Allahs Macht zu erinnern, bringt Vergebung und macht das Nachtgebet spezieller mit wahrem Iman und Barakah in jeder Niederwerfung.","lesson":"Allahs Macht wird erinnert, wenn Muslime dieses Dua für Sujood im Tahajjud nutzen."},{"id":227,"text":"Ich habe mein Gesicht vor Dem niedergeworfen, Der es erschaffen hat, und ihm Gehör und Sicht durch Seine Macht und Seine Kraft gegeben hat. So gesegnet ist Allah, der Beste der Schöpfer.","title":"Dua nach dem Rezitieren der Verse der Niederwerfung","source":"Sahih (Albani). Tirmidhi: 3425, Sure Al-Mu'minun 23:14","reflection":"Dieses Sujood-Dua nach Sajdah Tilawat in der Koranrezitation preist Allah als den besten Schöpfer, bringt Barakah und hilft einem Muslim, sich an Seine Macht und Barmherzigkeit in jeder Sajda nach dem Lesen des Koran zu erinnern.","lesson":"Allahs Größe wird mit diesem Sujood-Dua aus Surah Al Muminun im Koran gepriesen."},{"id":228,"text":"Alle Grüße der Demut sind für Allah, und alle Gebete und Güte. Friede sei mit dir, O Prophet, und die Barmherzigkeit Allahs und Seine Segnungen. Friede sei mit uns und mit den rechtschaffenen Dienern Allahs. Ich bezeuge, dass es niemanden gibt, der der Anbetung würdig ist außer Allah, und ich bezeuge, dass Muhammad Sein Diener und Sein Gesandter ist.","title":"Tashahhud Dua (Attahiyat Lillahi Wa Salawatu)","source":"Bukhari: 7381","reflection":"Dieses Tashahhud-Dua im Salah bringt Frieden, bestätigt den Glauben und verbindet einen Muslim mit Allah und Seinem Propheten, was jedes Attahiyat im Namaz voller Barakah und Akzeptanz macht.","lesson":"Attahiyat Lillahi Wa Salawatu bestätigt die Einheit Allahs und wahren Iman."},{"id":230,"text":"O Allah, schenke Muhammad (ﷺ) und seinen Frauen und Nachkommen Deine Gunst, wie Du der Familie von Ibrahim Deine Gunst geschenkt hast. Und segne Muhammad (ﷺ) und seine Frauen und Nachkommen, wie Du die Familie von Ibrahim gesegnet hast, Du bist voll des Lobes, All-Glorreich.","title":"Dua nach dem Tashahhud (Durood Sharif)","source":"Bukhari: 3369","reflection":"Dieses Dua nach Attahiyat bringt Segnungen und Frieden, verbindet Herzen mit dem Propheten Muhammad ﷺ und seiner Familie und bringt Allahs Barmherzigkeit für diejenigen, die es jeden Tag in ihrem Salah rezitieren.","lesson":"Allahumma Salli Ala Muhammad bringt Barakah und Rahmah in das Namaz eines Muslims."},{"id":231,"text":"O Allah, verbinde unsere Herzen, bessere unsere sozialen Beziehungen, leite uns auf den Weg des Friedens, bringe uns aus der Dunkelheit ins Licht, bewahre uns vor Obszönitäten, ob äußerlich oder innerlich, und segne unsere Ohren, unsere Augen, unsere Herzen, unsere Frauen, unsere Kinder, und lenke zu uns ein; Du bist der Einlenkende, der Barmherzige. Und mache uns dankbar für Deinen Segen und lass uns ihn preisen, während wir ihn annehmen, und gib ihn uns in Fülle.","title":"Dua Masura #1 (Allahumma Allif Baina Qulubina)","source":"Da'if (Schwach) (Albani). Abu Dawud: 969","reflection":"Dieses Dua Masura bringt Herzen zusammen, hilft Familien und Freunden, sich nahe zu bleiben, und bittet Allah um Frieden, Licht und Barakah in jedem Teil des Lebens eines Muslims, sowohl innen als auch außen.","lesson":"Allahumma Allif Baina Qulubina hält Liebe und Einheit stark in muslimischen Familien."},{"id":232,"text":"O Allah! Ich suche Zuflucht bei Dir vor der Pein der Hölle, vor der Pein des Grabes, vor der Prüfung von Leben und Tod und vor dem Übel der Prüfung des Masih al-Dajjal.","title":"Dua Masura #2 (Dua zum Schutz vor dem Höllenfeuer)","source":"Muslim: 588","reflection":"Dieses Dua Masura bittet Allah, Muslime sicher vor Jahannam, dem Grab und allen großen Prüfungen zu halten, was es zu einem starken Hifazat Ki Dua für das tägliche Amal und Iman jedes Gläubigen macht.","lesson":"Dua zum Schutz vor Bösem hält Muslime sicher vor Jahannams Strafe."},{"id":233,"text":"O Allah, vergib mir, was ich vor mir hergeschickt habe und was ich hinter mir gelassen habe, was ich verborgen habe und was ich offen getan habe, was ich im Übermaß getan habe, und wessen Du Dir bewusster bist als ich. Du bist derjenige, der vorausschickt, und Du bist derjenige, der verzögert. Es gibt niemanden, der der Anbetung würdig ist, außer Dir.","title":"Dua Masura #3 (Allahummaghfirli Ma Qaddamtu)","source":"Muslim: 771","reflection":"Dieses Dua Masura für Vergebung hilft Muslimen, Allah zu bitten, alle Sünden zu reinigen, verborgen oder offen, und bringt Hoffnung auf Maghfirat und Barmherzigkeit in jenes Muslims Amal und tägliches Salah.","lesson":"Allahummaghfirli Ma Qaddamtu wischt alte und neue Sünden aus dem Leben eines Muslims weg."},{"id":234,"text":"O Allah, ich habe mir selbst großes Unrecht getan und niemand vergibt Sünden außer Dir. Also gewähre mir Vergebung und habe Barmherzigkeit mit mir. Wahrlich, Du bist der Vergebende, der Barmherzige.","title":"Dua Masura #4 (Allahumma Inni Zalamtu Nafsi)","source":"Bukhari: 834","reflection":"Dieses Dua Masura im Namaz hilft Muslimen, ihre Fehler zuzugeben und Allah um Seine Maghfirat und Rahmah zu bitten, macht Herzen weich und bringt Hoffnung auf Vergebung in jedem Salah.","lesson":"Allahumma Inni Zalamtu Nafsi bringt Allahs Maghfirat für große und kleine Sünden."},{"id":236,"text":"O Allah, ich bitte Dich um alles Gute, in dieser Welt und im Jenseits, was ich weiß und was ich nicht weiß. O Allah, ich suche Zuflucht bei Dir vor allem Bösen, in dieser Welt und im Jenseits, was ich weiß und was ich nicht weiß. O Allah, ich bitte Dich um das Gute, um das Dich Dein Diener und Prophet (ﷺ) gebeten hat, und ich suche Zuflucht bei Dir vor dem Bösen, vor dem Dein Diener und Prophet (ﷺ) Zuflucht gesucht hat. O Allah, ich bitte Dich um das Paradies und um das, was einen ihm näher bringt, in Wort und Tat, und ich suche Zuflucht in Dir vor der Hölle und vor dem, was einen ihr näher bringt, in Wort und Tat. Und ich bitte Dich, jedes Urteil, das Du bezüglich meiner fällst, gut zu machen.","title":"Dua Masura #6 (Allahumma Inni As Aluka Min Khairi)","source":"Sahih (Albani). Ibn Madscha: 3846","reflection":"Dieses Dua Masura hilft einem Muslim, Allah um jede gute Sache und Sicherheit vor allem Schaden zu bitten, was das Herz im Amal stark macht und Hoffnung auf Jannah und Barakah in jedem Teil des Lebens bringt.","lesson":"Allah gibt einem Muslim Barakah und hält alles Böse fern mit Dua Masura."},{"id":237,"text":"O Allah, ich suche Zuflucht in Dir vor der Strafe des Grabes, und ich suche Zuflucht in Dir vor der Prüfung des Falschen Messias, und ich suche Zuflucht in Dir vor den Prüfungen von Leben und Tod. O Allah, ich suche Zuflucht in Dir vor Sünde und vor Schulden.","title":"Dua zum Schutz vor der Strafe des Grabes, der Hölle und Dajjal","source":"Bukhari: 832","reflection":"Dieses Dua Masura hält einen Muslim sicher vor den härtesten Prüfungen und bringt Allahs Hilfe in jedem Teil des Lebens, indem es um Barakah, Vergebung und Schutz vor allem Bösen und Fitna bittet.","lesson":"Allah hält einen Muslim sicher vor der Strafe des Grabes mit diesem Dua für Schutz."},{"id":238,"text":"O Allah, ich suche Zuflucht bei Dir vor der Pein der Hölle, und ich suche Zuflucht bei Dir vor der Pein des Grabes, und ich suche Zuflucht bei Dir vor der Prüfung des Masih al-Dajjal (Antichrist) und ich suche Zuflucht bei Dir vor der Prüfung von Leben und Tod. O Allah! Ich suche Zuflucht bei Dir vor Sünde und Schulden.","title":"Dua am Ende des Salah (Allahumma Inni A Uzu Bika)","source":"Muslim: 1/412","reflection":"Dieses Dua Masura hilft einem Muslim, Allahs Schutz vor jeder großen Prüfung zu finden, hält das Herz sicher vor Jahannam, Dajjal und der Last von Sünden und Schulden nach jedem Salah.","lesson":"Allah rettet einen Muslim vor Jahannams Azaab mit diesem Dua nach Salah."},{"id":240,"text":"O Allah! Ich suche Zuflucht bei Dir vor Feigheit und Geiz, und suche Zuflucht bei Dir vor dem Erreichen eines erniedrigten hilflosen Alters, und suche Zuflucht bei Dir vor den Bedrängnissen der Welt und vor der Bestrafung im Grab.","title":"Dua Masura #8 (Allahumma Inni A Uzu Bika Minal)","source":"Bukhari: 6374","reflection":"Dieses Dua Masura hilft einem Muslim, sicher vor den schlechten Dingen der Dunya zu bleiben, indem es Allah um Barakah, Mut und Schutz vor Grabes Azaab und jeder Fitna im Leben bittet.","lesson":"Allah hält einen Muslim fern von Bukhil und gibt Barakah mit diesem Schutz-Dua."},{"id":242,"text":"O Allah, ich bitte Dich. O Allah, Du bist der Eine, der Einzige, der unabhängige Herr, der nicht gezeugt wurde und nicht zeugt und niemand ist Ihm gleich. Vergib mir meine Sünden, wahrlich Du bist der Vergebende, der Barmherzige.","title":"Dua Masura #9 (Allahumma Inni As Aluka Ya Allah Bi'Annaka)","source":"Sahih (Albani). Nasa'i: 1301","reflection":"Dieses Dua Masura hilft einem Muslim, Allah um Vergebung zu bitten, indem es Ihn mit Seinen besonderen Namen anruft, bringt Barakah, Barmherzigkeit und Hoffnung auf Maghfirat in jeden Teil des Lebens.","lesson":"Allah vergibt Sünden und gibt Maghfirat mit diesem Dua Masura nach Salah."},{"id":243,"text":"O Allah, ich bitte Dich, da Dir alles Lob gebührt, niemand hat das Recht angebetet zu werden außer Dir, allein, ohne Partner. Du bist der Wohltäter. Urheber der Himmel und der Erde, O Besitzer von Majestät und Ehre, O ewig Lebender, O in Sich Selbst Bestehender und Erhalter von allem. Ich bitte Dich.","title":"Dua Masura #10","source":"Sahih (Albani). Nasa'i: 1300","reflection":"Dieses Dua Masura hilft einem Muslim, Allah mit Seinen schönsten Namen anzurufen, bringt Barakah, Hoffnung und Stärke in jedem Amal, indem er Ihn als Ya Hayyu Ya Qayyum und Ya Dhal Jalali Wal Ikram preist.","lesson":"Allah gibt Barakah und antwortet auf Dua, wenn man mit Ya Hayyu Ya Qayyum ruft."},{"id":244,"text":"O Allah, ich bitte Dich durch die Tatsache, dass ich bezeuge, dass Du Allah bist. Es gibt niemanden, der der Anbetung würdig ist, außer Dir, dem Einzigen Gott, unabhängig von der Schöpfung, Der nicht gezeugt wurde und nicht zeugt, und niemand ist Ihm gleich.","title":"Dua Masura #11 (Allahumma Inni As Aluka Bi Annaka Antallah Volles Dua)","source":"Sahih (Albani). Abu Dawud: 1493","reflection":"Dieses Dua Masura hilft einem Muslim, Allah bei Seinen besonderen Namen zu nennen, bringt Barakah, starken Iman und Hoffnung für jedes Amal, indem es sich erinnert, dass Er Al Ahad, Allahu Samad ist, und es niemanden wie Ihn gibt.","lesson":"Allah antwortet auf Dua, wenn ein Muslim Ihn mit La Ilaha Illa Anta und Allahumma ruft."},{"id":245,"text":"O Allah, ich bitte Dich, da Du der Eigentümer des Lobes bist, es gibt niemanden, der der Anbetung würdig ist, außer Dir allein, Du hast keinen Partner. Du bist der Geber alles Guten. O Schöpfer der Himmel und der Erde, Eigentümer von Majestät und Ehre. O Lebender und Ewiger, ich bitte Dich um das Paradies und ich suche Zuflucht bei Dir vor dem Feuer.","title":"Dua Masura #12","source":"Sahih (Albani). Abu Dawud: 1493-1495","reflection":"Dieses schöne Dua Masura bittet Allah um Jannah und Schutz vor Jahannam, unter Verwendung Seiner gesegneten Namen wie Ya Hayyu Ya Qayyum und Ya Dhal Jalali Wal Ikram, bringt Hoffnung und Frieden in jedes muslimische Herz.","lesson":"Allah gewährt dem Muslim Jannah, der dieses Dua Masura mit Iman macht."},{"id":248,"text":"Niemand hat das Recht angebetet zu werden außer Allah, der allein ist und keinen Partner hat. Ihm gehört alle Herrschaft und alles Lob, Er gibt Leben und verursacht den Tod und Er ist allmächtig über alle Dinge.","title":"Dua nach Fajr und Maghrib #1","source":"Hasan (Albani). Tirmidhi: 3534","reflection":"Dieses Dua nach Fajr-Gebet und Maghrib erinnert jeden Muslim an Allahs Einheit, Macht und Barmherzigkeit, macht das Herz stark mit Shahada und füllt den Tag und die Nacht mit Barakah und Frieden.","lesson":"La Ilaha Illallahu in diesem Dua nach Fajr-Gebet hält Iman stark und rein."},{"id":249,"text":"O Allah, beschütze mich vor der Hölle.","title":"Dua nach Fajr und Maghrib #2 (Allahumma Ajirni Minan Naar)","source":"Hasan (Ibn Hadschar). Al-Futuhat ar-Rabbaniyyah 3/69","reflection":"Dieses Dua nach Maghrib-Gebet und Fajr bittet Allah um Schutz vor Jahannam, macht jeden muslimischen Morgen und Abend voll von Hoffnung, Sicherheit und Allahs Barmherzigkeit im täglichen Leben.","lesson":"Allahumma Ajirni Minan Naar im Maghrib-Dua hält Muslime sicher vor Jahannam."},{"id":250,"text":"Ich bitte Allah um Vergebung.","title":"Dua nach dem Salah (Astaghfirullah)","source":"Sahih Muslim: 591","reflection":"Astaghfirullah nach Salah hilft jedem Muslim, Allahs Vergebung zu suchen, macht das Herz rein und bringt Barakah zu täglichem Amal, während die Seele Allahs Barmherzigkeit und Güte nahe bleibt.","lesson":"Astaghfirullah nach Salah wischt kleine Sünden und Fehler vom Amal weg."},{"id":251,"text":"O Allah, Du bist Frieden und von Dir kommt Frieden. Gesegnet bist Du, O Besitzer von Majestät und Ehre.","title":"Dua nach dem Salat (Allahumma Antas Salam Wa Minkas Salam Dua)","source":"Muslim: 591","reflection":"Dieses Dua nach dem Salat füllt das Herz mit Frieden von Allah, erinnert jeden Muslim daran, dass wahre Sicherheit und Barakah nur von Ihm kommen, und bringt Ehre durch das Rufen von Ya Zal Jalali Wal Ikram nach jedem Namaz.","lesson":"Allahumma Antas Salam im Dua nach dem Gebet bringt dem muslimischen Herzen echten Frieden."},{"id":252,"text":"Niemand hat das Recht angebetet zu werden außer Allah, allein, ohne Partner, Ihm gehört alle Herrschaft und alles Lob und Er ist fähig, alle Dinge zu tun. O Allah, niemand kann verhindern, was Du gewollt hast zu geben, und niemand kann geben, was Du gewollt hast zu verhindern, und kein Reichtum oder Majestät kann irgendjemandem nützen, da von Dir aller Reichtum und Majestät ist.","title":"Dua nach dem Salam","source":"Bukhari: 844","reflection":"Dieses Dua nach dem Salam erinnert jeden Muslim daran, dass alle Macht und Geschenke von Allah allein kommen, macht das Herz stark in Tawheed und füllt das tägliche Leben mit Barakah, Hoffnung und Vertrauen auf Allahs Plan.","lesson":"La Ilaha Illallahu Wahdahu La Sharika Lahu im Dua nach Salam hält Iman rein."},{"id":253,"text":"Niemand hat das Recht angebetet zu werden außer Allah, allein, ohne Partner, Ihm gehört alle Herrschaft und alles Lob und Er ist fähig, alle Dinge zu tun, es gibt keine Macht noch Kraft außer bei Allah. Niemand hat das Recht angebetet zu werden außer Allah und wir beten niemanden an außer Ihn. Für Ihn ist alle Gunst, Gnade und glorreiches Lob. Niemand hat das Recht angebetet zu werden außer Allah und wir sind aufrichtig im Glauben und in der Hingabe an Ihn, auch wenn die Ungläubigen es verabscheuen.","title":"Dua nach dem Salam im Gebet","source":"Muslim: 594","reflection":"Dieses Dua nach dem Salam im Gebet füllt das Herz mit Tawheed, Vertrauen und reinem Iman, erinnert jeden Muslim daran, dass alle Macht, alles Lob und alle Segnungen nur von Allah kommen, und hält die Seele mit täglichem Zikr sicher.","lesson":"La Ilaha Illallahu Wahdahu La Sharika Lahu im Dua nach dem Gebet hält den Glauben stark."},{"id":257,"text":"Wie perfekt Allah ist, alles Lob ist für Allah, und Allah ist der Größte.","title":"Kraftvoller Dhikr nach dem Salah","source":"Muslim 1/418, Nr. 597","reflection":"Dieser Dhikr nach dem Salat füllt das Herz mit Frieden und bringt Allahs Barmherzigkeit nahe, was jeden Muslim die Segnungen von Subhanallah Alhamdulillah Allahu Akbar im täglichen Leben fühlen lässt.","lesson":"Subhanallah und Alhamdulillah mit Allahu Akbar machen Iman nach jedem Salah stark."},{"id":258,"text":"O Allah, rette mich vor Deiner Bestrafung an dem Tag, an dem Du Deine Sklaven auferweckst - oder versammelst.","title":"Dua am Ende des Salah","source":"Muslim: 709","reflection":"Dieses Dua am Ende des Salah bittet Allah um Sicherheit vor Seiner Bestrafung und bringt Hoffnung für jeden Muslim, der Vergebung und Barmherzigkeit am Tag will, an dem alle Menschen vor Ihm stehen werden.","lesson":"Allahs Barmherzigkeit kommt nahe für den Muslim, der Dua nach Salah mit Yaqeen macht."},{"id":259,"text":"O Allah, ich suche Zuflucht bei Dir vor Kufr, Armut und vor der Qual des Grabes.","title":"Dua am Ende des Salah","source":"Sahih (Albani). Nasa'i: 5465","reflection":"Dieses Dua am Ende des Salah bittet Allah um Schutz vor Kufr, Armut und dem Schmerz des Grabes, was jedem Muslim Hoffnung auf Sicherheit und Frieden in dieser Welt und der nächsten gibt.","lesson":"Allahumma Inni Auzubika hält einen Muslim sicher vor Kufr und schwachem Iman nach Salah."},{"id":260,"text":"O Allah, hilf mir, Deiner zu gedenken, Dir zu danken und Deinen Gottesdienst in der besten Weise auszuführen.","title":"Dua nach dem Salah (Allahumma a inni ala zikrika wa shukrika)","source":"Sahih (Albani). Abu Dawud: 1522","reflection":"Dieses Dua nach Salah bittet Allah um Hilfe, Seiner zu gedenken, Dank zu geben und Ibadah auf die beste Weise zu tun, was das Herz jedes Muslims nach jedem Gebet voll von Zikr und Shukr macht.","lesson":"Allahumma A Inni Ala Zikrika Wa Shukrika bringt Barakah in jedes muslimische Amal."},{"id":261,"text":"O Allah, vergib mir, was ich vorangeschickt habe und was ich zurückgelassen habe, was ich im Geheimen getan habe und was ich öffentlich getan habe, was ich im Übermaß getan habe, und jene Sünden, die Dir besser bekannt sind als mir. Du bist der Eine, Der vorauseilt, und Du bist der Eine, Der verzögert. Es gibt niemanden, der der Anbetung würdig ist, außer Dir.","title":"Dua nach dem Namaz","source":"[1] Muslim: 771 [2] Sahih (Albani). Abu Dawud: 1509","reflection":"Dieses Dua nach dem Namaz bittet Allah um Vergebung jeder Sünde, versteckt oder offen, und bringt Hoffnung auf Barmherzigkeit für jeden Muslim, der nach jedem Salah ein reines Herz und Allahs Vergebung möchte.","lesson":"Allahummaghfirli Ma Qaddamtu hilft einem Muslim, Vergebung für alle vergangenen Fehler zu bekommen."},{"id":262,"text":"O Allah, richte meine religiöse Verpflichtung, die Du zu einem Schutz für mich gemacht hast, und richte meine weltlichen Angelegenheiten, die Du zu einem Mittel meines Lebensunterhalts gemacht hast. O Allah, ich suche Zuflucht in Deinem Wohlgefallen vor Deinem Zorn, und ich suche Zuflucht in Deiner Vergebung vor Deiner Bestrafung, und ich suche Zuflucht in Dir vor Dir. O Allah, niemand kann zurückhalten, was Du gegeben hast, und niemand kann geben, was Du zurückgehalten hast, und kein Reichtum oder Glück kann dem Mann von Reichtum und Glück vor Dir nützen.","title":"Dua am Ende des Namaz","source":"Hasan (Ibn Hadschar). Al-Futuhat ar-Rabbaniyyah 3/71","reflection":"Dieses Dua am Ende des Namaz bittet Allah, sowohl Deen als auch Dunya zu richten, und bringt Seine Barmherzigkeit und Hilfe zu jedem Muslim, der ein gutes Leben und starken Iman nach jedem Salah möchte.","lesson":"Allahumma La Mania Lima Ataita hält Rizq sicher und bringt Barakah im täglichen Leben."},{"id":263,"text":"Ya Allah! Ich versuche durch Deine Hilfe, kämpfe durch Deine Hilfe, zeige Mut durch Deine Hilfe und bin siegreich durch Deine Hilfe.","title":"Dua nach dem Gebet","source":"Sahih (Albani). Darimi: 2/217","reflection":"Dieses Dua nach dem Gebet bittet Allah um Hilfe in jedem Kampf, macht einen Muslim stark und mutig mit Seiner Unterstützung in jedem Teil des Lebens nach jedem Salah.","lesson":"Allahumma gibt einem Muslim Stärke, Mushkil zu begegnen und mit Allahs Hilfe zu gewinnen."},{"id":264,"text":"O Allah, vergib mir und wende Dich mir zu. Du bist der sich ständig Zuwendende, der Barmherzige (in einer anderen Überlieferung: der Allvergebende)","title":"Dua nach dem Salat (Allahummaghfirli Warhamni Wa Tub Alayya)","source":"Sahih (Albani). Sahihah: 556, Ahmad: 5564","reflection":"Dieses Dua nach dem Salat bittet Allah um Vergebung und Barmherzigkeit, hilft jedem Muslim, Hoffnung und ein reines Herz nach jedem Gebet zu finden, indem er auf Allahs Güte und Seine Macht, Tawbah zu akzeptieren, vertraut.","lesson":"Allahummaghfirli Warhamni bringt Allahs Barmherzigkeit und wischt alte Sünden nach Salat weg."},{"id":265,"text":"Ya Allah! Vergib alle meine Fehler und meine Sünden. Ya Allah! Inspiriere mich und mache mich gehorsam. Leite mich an, die guten Taten zu tun und zu den guten Manieren. Denn niemand kann zu dessen Gutem leiten und sich davon abwenden außer Dir.","title":"Dua für nach dem Namaz","source":"Hasan (Albani). Sahih al-Dschami: 1266","reflection":"Dieses Dua für nach dem Namaz hilft einem Muslim, Allah um Vergebung und gute Manieren zu bitten, was jedes Salah zu einer Zeit macht, um Seine Barmherzigkeit und Führung für bessere Handlungen und ein reines Herz zu suchen.","lesson":"Allahumma in diesem Dua nach Namaz bringt Vergebung für alle Fehler und Sünden."},{"id":266,"text":"O Allah, vergib mir meine Sünde und erweitere für mich meine Wohnstätte und segne für mich das, was Du mir gewährt hast.","title":"Dua für nach dem Salah","source":"Hasan (Albani). Sahih al-Dschami: 1265","reflection":"Dieses Dua für nach dem Salah hilft einem Muslim, Allah um Vergebung, Barakah im Rizq und ein friedliches Zuhause zu bitten, was jedes Gebet zu einer Zeit macht, um Seine Barmherzigkeit und Segnungen für das tägliche Leben und die Familie zu suchen.","lesson":"Allahumma in diesem Dua nach Salah bringt Allahs Vergebung für jede Sünde."},{"id":267,"text":"Allah ist der Größte.","title":"Dhikr nach dem Salah","source":"Bukhari: 842","reflection":"Allahu Akbar nach dem Salah zu sagen erinnert einen Muslim daran, dass Allah der Größte ist, was dem Herzen Frieden bringt und jedes Gebet durch die Kraft von Takbir und wahrem Iman stärker macht.","lesson":"Takbir nach Salah hebt das Herz und hält Allahs Größe im Geist."},{"id":268,"text":"Ruhm ist für Allah und Lob ist für Ihn, durch die Vielzahl Seiner Schöpfung, durch Sein Wohlgefallen, durch das Gewicht seines Thrones, und durch das Ausmaß Seiner Worte.","title":"Namaz nach Dua","source":"Muslim: 2726","reflection":"Subhanallahi Wa Bihamdihi nach Namaz zu sagen, füllt das Herz mit Lob für Allah, was jedes Gebet stärker macht und Sein Wohlgefallen, Barmherzigkeit und Segnungen ins tägliche Leben bringt.","lesson":"Subhanallahi Wa Bihamdihi im Tasbih nach Namaz bringt Allahs Wohlgefallen und Barmherzigkeit."},{"id":273,"text":"Ruhm sei Dir, O Allah, und Lob. Gesegnet ist Dein Name und Erhaben ist Deine Majestät. Es gibt niemanden, der der Anbetung würdig ist, außer Dir.","title":"Dua für den Beginn des Tahajjud-Gebets (Subhanaka Allahumma)","source":"Sahih (Albani). Abu Dawud: 775","reflection":"Dieses Dua für den Beginn des Tahajjud-Gebets füllt das Herz mit Allahs Lob, macht das Nachtgebet stärker und bringt Barakah, Barmherzigkeit und Nähe zu Allah in jedem Tahajjud.","lesson":"Subhanaka Allahumma im Tahajjud-Gebet bringt Allahs Barakah und Barmherzigkeit."},{"id":274,"text":"Ruhm sei dem König, dem Heiligen.","title":"Dua nach dem Witr-Gebet (Subhanal Malikil Quddus)","source":"Sahih (Albani). Abu Dawud Nr. 1430; An-Nasa'i Nr. 1699, 1701","reflection":"Subhanal Malikil Quddus nach dem Witr-Gebet zu sagen, füllt das Herz mit Allahs Größe, macht das Ende des Nachtgebets besonders und bringt Frieden, Barakah und Reinheit für jeden Muslim.","lesson":"Subhanal Malikil Quddus im Dua nach dem Witr-Gebet bringt Allahs Reinheit und Lob."},{"id":276,"text":"Herr der Engel und des Geistes.","title":"Dua nach dem Witr Salah (Rabbul-mala'ikati war ruh)","source":"Sunan Darakutni 2/31, Mu'jamul-Awsat 8/108, Sunan Bayhaki 3/40","reflection":"Dieses Dua nach dem Witr Salah erinnert einen Muslim an Allahs Macht über alle Engel und Jibril, was das Ende des Nachtgebets voller Lob, Barakah und Nähe zum Herrn der Engel macht.","lesson":"Dua nach Witr Salah mit Rabbul-mala'ikati War Ruh zeigt Allahs Größe."},{"id":278,"text":"O Allah, leite mich mit denen, die Du geleitet hast, und stärke mich mit denen, denen Du Stärke gegeben hast. Nimm mich in Deine Obhut mit denen, die Du in Deine Obhut genommen hast. Segne mich in dem, was Du mir gegeben hast. Beschütze mich vor dem Übel, das Du bestimmt hast. Wahrlich, Du befiehlst und wirst nicht befohlen, und niemand, den Du Deiner Obhut übergeben hast, soll gedemütigt werden und niemand, den Du als Feind genommen hast, soll Ruhm kosten. Du bist Gesegnet, Unser Herr, und Erhaben.","title":"Dua für Witr (Dua Qunut)","source":"Sahih (Albani). Abu Dawud: 1425","reflection":"Dua für Witr, bekannt als Dua E Qunoot, bringt Allahs Führung, Schutz und Barakah, macht das Nachtgebet stark und füllt das Herz mit Hoffnung, Sicherheit und wahren Segnungen von Allah.","lesson":"Dua für Witr bittet Allah um Hidayah und hält einen Muslim auf dem richtigen Pfad."},{"id":279,"text":"Mein Herr, hilf mir und hilf nicht gegen mich, und gewähre mir Sieg und gewähre keinen Sieg über mich, plane für mich und plane nicht gegen mich, leite mich und erleichtere Führung für mich, gewähre mir Sieg über jene, die gegen mich übertreten. Mein Herr, mache mich Dir stets dankbar, Deiner stets gedenkend, Dich stets fürchtend, Dir stets gehorsam, Dir stets demütig, oft zu Dir wendend und zurückkehrend. Mein Herr, akzeptiere meine Reue, wasche meine Sünde, antworte meinem Ruf, mache meinen Beweis fest, mache meine Zunge fest, leite mein Herz und entferne Groll aus meinem Herzen (den Verrat meiner Brust).","title":"Dua e Qunut (Rabbi A'inni Wala Tu'in 'Alayya)","source":"Sahih (Albani). Tirmidhi: 3551","reflection":"Dieses Dua E Qunoot bringt einen Muslim näher an Allahs Hilfe und Barmherzigkeit, bittet um Stärke, Führung und Vergebung in jedem Teil des Lebens, besonders in Zeiten der Not und Härte.","lesson":"Allah gibt demjenigen Stärke und Hilfe, der Dua E Qunoot mit Iman macht."},{"id":280,"text":"O Allah, Dich allein beten wir an und zu Dir beten wir und werfen uns nieder. Zu Dir eilen wir, um zu dienen und zu dienen. Unsere Hoffnung ist auf Deine Barmherzigkeit und wir fürchten Deine Bestrafung. Wahrlich, Deine Bestrafung der Ungläubigen ist nahe. O Allah, wir suchen Deine Hilfe und Deine Vergebung, und wir preisen Dich wohltätig. Wir verleugnen Dich nicht und wir glauben an Dich. Wir ergeben uns Dir und sagen uns von dem los, der Dich verleugnet.","title":"Dua Qunut (Allahumma inna nasta inuka)","source":"Sahih (Albani). Irwa' al-Ghalil: 2/170, Baihaqi: As-Sunan al-Kubra - 2/211","reflection":"Dieses Dua Qunoot im Witr-Gebet hilft einem Muslim, wahren Glauben zu zeigen, um Allahs Barmherzigkeit zu bitten und Vergebung zu suchen, was das Herz weich und voll Hoffnung in jedem Salah und jeder Härte macht.","lesson":"Allahumma Inna Nasta Inuka bringt Allahs Hilfe und Vergebung im Witr-Gebet."},{"id":282,"text":"Allah ist der Größte.","title":"Beim Aufwachen für das Tahajjud-Gebet (Dhikr & Dua)","source":"Hasan (Albani). Abu Dawud: 766","reflection":"Allahu Akbar vor dem Tahajjud-Gebet zu sagen füllt das Herz mit Stärke und hilft einem Muslim, sich an Allahs Größe in der Stille der Nacht zu erinnern, was jedes Tahajjud besonders und voller Barakah macht.","lesson":"Allahu Akbar vor Tahajjud bringt das Herz nah an Allahs Größe."},{"id":284,"text":"(135) Und diejenigen, die, wenn sie eine Unmoral begehen oder sich selbst unrecht tun [durch Übertretung], Allahs gedenken und Vergebung für ihre Sünden suchen - und wer kann Sünden vergeben außer Allah? - und [die] nicht in dem verharren, was sie getan haben, während sie wissen. (136) Jene - ihr Lohn ist Vergebung von ihrem Herrn und Gärten, unter denen Flüsse fließen [im Paradies], worin sie ewig verweilen werden; und ausgezeichnet ist der Lohn der [rechtschaffenen] Arbeitenden. (Sure Ali Imran 3:135-136)","title":"Dua für Reue nach Sünde (2 Rakat Gebet)","source":"Sahih (Albani). Abu Dawud: 1521","reflection":"Dieses Dua für Reue nach Sünde hilft einem Muslim, mit reinem Herzen zu Allah zurückzukehren, Vergebung und Barmherzigkeit zu suchen, und bringt Hoffnung auf Jannah und einen Neuanfang nach jedem Fehler.","lesson":"Dua für Reue bringt Allahs Vergebung und wischt alte Sünden schnell weg."},{"id":285,"text":"O Allah, vergib ihm (Name der Person), erhöbe seinen Rang unter denen, die rechtgeleitet sind, gewähre ihm einen Nachfolger in seinen Nachkommen, die bleiben. Vergib uns und ihm, O Herr des Universums, und mache sein Grab geräumig, und gewähre ihm Licht darin.","title":"Dua für den Verstorbenen","source":"Muslim: 920","reflection":"Dieses Dua für den Verstorbenen bringt Hoffnung und Barmherzigkeit für denjenigen, der verstorben ist, und bittet Allah zu vergeben, Licht im Grab zu geben und ihren Platz unter den Rechtgeleiteten mit Barakah für ihre Familie zu erhöhen.","lesson":"Dua für den Verstorbenen bittet Allah zu vergeben und den Darajat der Person zu erhöhen."},{"id":287,"text":"Mit dem Namen Allahs und gemäß der Sunnah des Gesandten Allahs (ﷺ).","title":"Dua beim Hineinlegen des Verstorbenen ins Grab","source":"Sahih. Abu Dawud: 3213","reflection":"Dieses Dua für das Grab bringt Frieden und Barakah beim Platzieren des Verstorbenen, folgt der Sunnah und bittet Allah, das Begräbnis leicht und voller Barmherzigkeit für denjenigen im Grab zu machen.","lesson":"Bismillah beim Begräbnis hält das Grab sicher mit Allahs Namen und Schutz."},{"id":288,"text":"Mit dem Namen Allahs und gemäß der Millat des Gesandten Allahs (ﷺ).","title":"Dua beim Hineinlegen des Körpers ins Grab","source":"Sahih. Ibn Madschah: 1550","reflection":"Dieses Dua für die Beerdigung bringt Trost und Barakah beim Platzieren des Körpers im Grab, folgt dem Weg des Gesandten Allahs und bittet um Allahs Barmherzigkeit und Schutz für den Verstorbenen.","lesson":"Bismillah beim Begräbnis gibt dem Grab Sicherheit und Frieden mit Allahs Namen."},{"id":289,"text":"Mit dem Namen Allahs, auf dem Weg Allahs und gemäß der Millat des Gesandten Allahs (ﷺ)","title":"Dua beim Hineinlegen des Körpers ins Grab","source":"Sahih. Ibn Madschah: 1270","reflection":"Dieses Dua für die Toten bringt Frieden und Barmherzigkeit beim Platzieren des Körpers im Grab, folgt dem Pfad Allahs und des Gesandten und bittet um Barakah und Sicherheit für den Verstorbenen.","lesson":"Bismillah beim Begräbnis gibt dem Grab Schutz und Allahs besondere Fürsorge."},{"id":290,"text":"Friede sei mit euch, den Bewohnern des Grabes, unter den Gläubigen und Muslimen, und wenn Allah will, dann werden wir uns euch anschließen. Ich bete zu Allah um Frieden für uns und für euch.","title":"Dua für den Besuch des Grabes (Assalamualaikum ya ahlal quboor)","source":"Muslim: 975","reflection":"Dieses Dua für den Besuch des Grabes bringt Frieden sowohl den Lebenden als auch denen, die ruhen, erinnert uns an unsere Rückkehr zu Allah und das Band zwischen Muslimen sogar nach dem Tod.","lesson":"Allah gibt demjenigen Barakah, der Dua für den Besuch des Grabes mit Iman macht."},{"id":291,"text":"Friede sei mit den Bewohnern dieses Ortes unter den Gläubigen und Muslimen. Möge Allah mit denen Erbarmen haben, die uns vorausgegangen sind, und denen, die später kommen, und wir werden uns euch anschließen, so Allah will.","title":"Dua für das Betreten des Friedhofs (Masnoon Dua)","source":"Sahih. Mischkat al-Masabih: 1767","reflection":"Dieses Dua für das Betreten des Friedhofs erinnert Muslime an die Kürze des Lebens, bringt Barmherzigkeit für diejenigen, die verstorben sind, und hält das Herz weich mit Hoffnung auf Allahs Vergebung und Güte.","lesson":"Allah zeigt Rahmah gegenüber Muslimen, die dieses Dua für das Betreten des Friedhofs nutzen."},{"id":292,"text":"Friede sei mit euch, o ihr, die ihr glaubt. Wir werden euch treffen, so Allah will.","title":"Dua für den Besuch des Grabes (Friedhofs-Dua)","source":"Muslim: 249","reflection":"Dieses Dua für den Besuch des Friedhofs bringt Frieden in die Herzen, verbindet Gläubige und erinnert uns an unsere eigene Rückkehr zu Allah, was jeden Besuch voll von Hoffnung und Güte macht.","lesson":"Allah gibt den Toten Frieden, wenn Muslime Assalamualaikum am Friedhof sagen."},{"id":293,"text":"Friede sei mit euch, o ihr gläubigen Bewohner des Grabes! Das Versprechen, das euch gegeben wurde, ist zu euch gekommen, und ihr wartet auf den Tag, der kommen wird. Und wir werden uns euch durch den Willen Allahs anschließen. O Allah, vergib den Bewohnern des Baqi-Friedhofs.","title":"Dua für den Besuch muslimischer Gräber (Friedhofs-Dua)","source":"Muslim: 974","reflection":"Dieses Dua für Friedhof bringt Hoffnung auf Vergebung, verbindet Herzen mit denen, die ruhen, und erinnert jeden Muslim an Allahs Versprechen und die Barmherzigkeit, die auf alle Gläubigen wartet.","lesson":"Allah gibt Maghfirat für die Toten, wenn Muslime dieses Dua für Friedhof nutzen."}];
